#!/usr/bin/env bash
# cis-audit.sh - read-only CIS Ubuntu Linux 26.04 LTS Benchmark v1.0.0 audit
# (Level 1 - Server). Writes a text and an HTML report. Never changes the system.
#
#   cis-audit.sh --help
#
# Internal compliance check, not an official CIS-CAT result. CIS benchmark content
# is licensed for internal use only.
set -o pipefail
set -u

export LC_ALL=C
if [[ -z ${CIS_AUDIT_TESTMODE-} ]]; then
    PATH=/usr/sbin:/usr/bin:/sbin:/bin
fi

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" >/dev/null 2>&1 && pwd -P)

# ---- bundled libraries (generated by tools/build_single.sh) ----

# ==== lib/core.sh ====
# lib/core.sh - shared state, result recording, logging and small helpers.
# Sourced by cis-audit.sh. Defines functions and default globals only.
# shellcheck disable=SC2034  # globals are consumed by the other libs

CIS_VERSION="1.0.0"
CIS_BENCH_NAME="CIS Ubuntu Linux 26.04 LTS Benchmark"
CIS_BENCH_VERSION="v1.0.0"

# bash 5.2 turns "&" in a ${var//pat/repl} replacement into the matched text.
shopt -u patsub_replacement 2>/dev/null || true

# ---------------------------------------------------------------- state ----
VALID_STATES=" PASS FAIL EXCEPTION MANUAL N/A SKIPPED ERROR "
declare -A R_STATE=() R_EVID=() R_NOTE=()   # per control id
declare -A EXC_JUST=() EXC_BY=() EXC_EXP=() # exceptions by id
declare -A SITE=()                          # site.conf values
declare -A P=()                             # params of the control being run
CHECK_TIMEOUT=60
VERBOSE=0
QUIET=0
USE_COLOR=0
R=""                                        # root prefix for file reads (tests only)
[[ -n ${CIS_AUDIT_TESTMODE-} ]] && R=${CIS_AUDIT_ROOTFS:-}
CUR_ID=""

# --------------------------------------------------------------- output ----
init_colors() {
    C_RED="" C_GRN="" C_YEL="" C_BLU="" C_DIM="" C_RST=""
    if (( USE_COLOR )); then
        C_RED=$'\e[31m' C_GRN=$'\e[32m' C_YEL=$'\e[33m' C_BLU=$'\e[34m'
        C_DIM=$'\e[2m' C_RST=$'\e[0m'
    fi
}

log_err()  { printf 'cis-audit: %s\n' "$*" >&2; }
log_warn() { (( QUIET )) || printf 'cis-audit: warning: %s\n' "$*" >&2; }
log_info() { (( QUIET )) || printf '%s\n' "$*" >&2; }
log_verbose() { (( VERBOSE )) && printf '%s\n' "$*" >&2; return 0; }

# Usage/precondition errors end the run with exit code 3.
die_usage() {
    log_err "$*"
    exit 3
}

# ------------------------------------------------------------- results ----
# result <ID> <STATE> <evidence line>...
# Every check ends with exactly one call. Evidence says what was found and what
# was expected.
result() {
    local id=$1 state=$2
    shift 2
    if [[ $VALID_STATES != *" $state "* ]]; then
        state=ERROR
        set -- "internal error: invalid state requested for $id"
    fi
    if (( $# == 0 )); then
        set -- "(check returned no evidence)"
    fi
    # An evidence line starting with "!" is a finding: it is moved to the front
    # (marker removed) so the reason for a FAIL is the first line an admin reads.
    local e
    local -a first=() rest=()
    for e in "$@"; do
        if [[ $e == '!'* ]]; then first+=("${e:1}"); else rest+=("$e"); fi
    done
    local IFS=$'\n'
    R_STATE[$id]=$state
    R_EVID[$id]="${first[*]}${first[*]:+$'\n'}${rest[*]}"
    RESULT_SET=1
}

# Run one check with a clean result flag; a check that forgets to call result()
# is reported as ERROR rather than silently dropped.
run_check_fn() {
    local fn=$1 id=$2
    RESULT_SET=0
    "$fn" "$id"
    if (( ! RESULT_SET )); then
        result "$id" ERROR "check function $fn did not report a result"
    fi
}

# ------------------------------------------------------------- helpers -----
tmo() { timeout -k 3 "$CHECK_TIMEOUT" "$@"; }

# Like tmo, but only a timeout (124) or a missing binary (127) is a failure.
tmo_tol() {
    tmo "$@"
    local rc=$?
    (( rc == 124 || rc == 127 )) && return 1
    return 0
}

trim() {
    local s=$1
    s="${s#"${s%%[![:space:]]*}"}"
    s="${s%"${s##*[![:space:]]}"}"
    REPLY=$s
}

is_uint() { [[ ${1-} =~ ^[0-9]+$ ]]; }
is_int()  { [[ ${1-} =~ ^-?[0-9]+$ ]]; }

# list_has "a,b,c" item  (separator "," or "|")
list_has() {
    local list=$1 item=$2 x
    local IFS=',|'
    for x in $list; do
        [[ $x == "$item" ]] && return 0
    done
    return 1
}

# oct_excess <actual-octal> <max-octal>: prints the permission bits in actual
# that are not allowed by max (as octal). Returns 0 when nothing is excess.
oct_excess() {
    local a=$((8#${1:-0})) m=$((8#${2:-0})) x
    x=$(( a & ~m & 07777 ))
    printf -v OCT_EX '%04o' "$x"
    (( x == 0 ))
}

# mode4 <octal>: M4 = the mode as four octal digits ("0644"). No subshell.
mode4() { printf -v M4 '%04o' "$((8#${1:-0}))"; }

# html_escape <string>  -> REPLY. One helper for every value taken from the host.
html_escape() {
    local s=$1
    s=${s//&/'&amp;'}
    s=${s//</'&lt;'}
    s=${s//>/'&gt;'}
    s=${s//\"/'&quot;'}
    s=${s//\'/'&#39;'}
    REPLY=$s
}

# Replace control characters in text that came from the host (log files and
# usernames may hold anything) so reports cannot carry terminal escapes.
sanitize() {
    REPLY=${1//[^[:print:]$'\n'$'\t']/?}
}

# Resolve "@NAME:default" parameter values against site.conf.
site_val() {
    local name=$1 def=$2
    REPLY=${SITE[$name]:-$def}
}

# Parse "k=v;k=v" into the global P array. Values may contain "=" (first one splits).
parse_params() {
    local spec=$1 kv k v
    P=()
    [[ -z $spec || $spec == "-" ]] && return 0
    local IFS=';'
    for kv in $spec; do
        k=${kv%%=*}
        v=${kv#*=}
        [[ $kv == *=* ]] || v=""
        if [[ $v == @*:* ]]; then
            local nm=${v#@} df=${v#*:}
            nm=${nm%%:*}
            site_val "$nm" "$df"
            v=$REPLY
        fi
        P[$k]=$v
    done
}

# Calendar helpers without date(1): days since 1970-01-01 for YYYY-MM-DD.
days_from_civil() {
    local y=$1 m=$2 d=$3 era yoe doy doe
    m=$((10#$m)) d=$((10#$d))
    (( m <= 2 )) && y=$((y - 1))
    era=$(( (y >= 0 ? y : y - 399) / 400 ))
    yoe=$(( y - era * 400 ))
    doy=$(( (153 * (m > 2 ? m - 3 : m + 9) + 2) / 5 + d - 1 ))
    doe=$(( yoe * 365 + yoe / 4 - yoe / 100 + doy ))
    REPLY=$(( era * 146097 + doe - 719468 ))
}

valid_date() {
    [[ ${1-} =~ ^([0-9]{4})-([0-9]{2})-([0-9]{2})$ ]] || return 1
    local y=${BASH_REMATCH[1]} m=$((10#${BASH_REMATCH[2]})) d=$((10#${BASH_REMATCH[3]}))
    (( m >= 1 && m <= 12 && d >= 1 && d <= 31 )) || return 1
    local dim=(0 31 28 31 30 31 30 31 31 30 31 30 31)
    if (( m == 2 )) && { (( y % 4 == 0 && y % 100 != 0 )) || (( y % 400 == 0 )); }; then
        dim[2]=29
    fi
    (( d <= dim[m] ))
}

# Read a file's lines with comments and blanks removed; prints to stdout.
strip_comments() {
    local f=$1
    [[ -r $f ]] || return 1
    grep -Pv '^\s*(#|$)' -- "$f"
}

# Sort IDs like 1.2.10 after 1.2.9
sort_ids() { LC_ALL=C sort -t. -k1,1n -k2,2n -k3,3n -k4,4n -k5,5n; }

# Truncate for one-line display
trunc() {
    local s=$1 n=$2
    if (( ${#s} > n )); then
        REPLY="${s:0:n-3}..."
    else
        REPLY=$s
    fi
}

# ==== lib/facts.sh ====
# lib/facts.sh - lazy, read-only fact collectors and parsed fact accessors.
#
# Every external command the audit runs lives in a collect_* function in this
# file. Collected output is cached as one file per fact in $FACTS_DIR. Checks
# never run commands; they call need <fact>... and read the parsed arrays.
#
# Test mode (CIS_AUDIT_FACTS_DIR set): facts are never collected, a missing fact
# file means "unavailable" and file reads go through the fixture root $R.
# shellcheck disable=SC2034

FACTS_DIR=""
FIXTURE_MODE=0
FACT_FILE=""
declare -A FACT_STATE=() FACT_ERR=()

# fact <name> [arg]  - make sure a fact is cached. Sets FACT_FILE.
fact() {
    local n=$1 arg=${2-} key
    key=$n
    [[ -n $arg ]] && key="$n.${arg//[^A-Za-z0-9._-]/_}"
    FACT_FILE="$FACTS_DIR/$key"
    case ${FACT_STATE[$key]-} in
        ok) return 0 ;;
        fail) return 1 ;;
    esac
    if [[ -e $FACT_FILE ]]; then
        FACT_STATE[$key]=ok
        return 0
    fi
    if (( FIXTURE_MODE )) || ! declare -F "collect_$n" >/dev/null; then
        FACT_STATE[$key]=fail
        FACT_ERR[$key]="not available in the facts directory"
        return 1
    fi
    log_verbose "collecting fact: $key"
    if "collect_$n" "$arg" >"$FACT_FILE.tmp" 2>"$FACT_FILE.err"; then
        mv -f -- "$FACT_FILE.tmp" "$FACT_FILE"
        FACT_STATE[$key]=ok
        return 0
    fi
    FACT_STATE[$key]=fail
    FACT_ERR[$key]=$(head -n1 "$FACT_FILE.err" 2>/dev/null)
    [[ -n ${FACT_ERR[$key]} ]] || FACT_ERR[$key]="command failed or timed out"
    rm -f -- "$FACT_FILE.tmp"
    return 1
}

# need <logical-fact>... : load facts for the current check or report ERROR.
need() {
    local x
    for x in "$@"; do
        if ! "need_$x"; then
            result "$CUR_ID" ERROR "required fact '$x' is unavailable: ${NEED_ERR:-unknown reason}"
            return 1
        fi
    done
    return 0
}
NEED_ERR=""
_need_fact() { # _need_fact <fact> [arg]
    if fact "$@"; then return 0; fi
    local key=$1
    [[ -n ${2-} ]] && key="$1.${2//[^A-Za-z0-9._-]/_}"
    NEED_ERR="$key: ${FACT_ERR[$key]-unknown}"
    return 1
}

# ----------------------------------------------------------- collectors ----
# Each collector prints the fact on stdout and returns 0 when the fact is usable.
find_bin() { # find_bin <name> -> BIN
    BIN=""
    local d
    for d in /usr/sbin /usr/bin /sbin /bin; do
        if [[ -x $d/$1 ]]; then BIN=$d/$1; return 0; fi
    done
    return 1
}

collect_dpkg() { tmo dpkg-query -W -f '${Package}\t${db:Status-Status}\t${Version}\n'; }
collect_unit_files() { tmo_tol systemctl list-unit-files --no-pager --no-legend; }
collect_units_all() { tmo_tol systemctl list-units --all --no-pager --no-legend --plain; }
collect_mounts() { tmo findmnt -knP -o TARGET,SOURCE,FSTYPE,OPTIONS; }
collect_sysctl_running() { tmo_tol sysctl -a 2>/dev/null; }
collect_sysctl_cat() {
    local b
    for b in /usr/lib/systemd/systemd-sysctl /lib/systemd/systemd-sysctl; do
        [[ -x $b ]] && { tmo "$b" --cat-config; return; }
    done
    return 1
}
collect_sshd_T() {
    find_bin sshd || return 1
    tmo "$BIN" -T
}
collect_sshd_T_C() {
    find_bin sshd || return 1
    tmo "$BIN" -T -C user=root,host=localhost,addr=127.0.0.1
}
collect_modprobe_cfg() { find_bin modprobe && tmo "$BIN" --showconfig; }
collect_lsmod() { tmo lsmod; }
collect_kmod_files() {
    tmo find /usr/lib/modules -type f \( -name '*.ko' -o -name '*.ko.*' \) \
        \( -path '*/kernel/fs/*' -o -path '*/kernel/net/*' \
        -o -path '*/kernel/drivers/firewire/*' -o -path '*/kernel/drivers/usb/storage/*' \) -print 2>/dev/null
    return 0
}
collect_ss_listen() { find_bin ss && tmo "$BIN" -plntuH; }
collect_ufw_status() { find_bin ufw && tmo "$BIN" status verbose; }
collect_apt_config() { find_bin apt-config || BIN=apt-config; tmo "$BIN" dump; }
collect_apt_policy() {
    tmo apt-cache policy libpam-runtime libpam-modules libpam-pwquality cracklib-runtime
}
collect_catcfg() { # systemd-analyze cat-config <name>
    local a
    for a in /usr/bin/systemd-analyze /bin/systemd-analyze; do
        [[ -x $a ]] && { tmo "$a" cat-config "$1"; return; }
    done
    return 1
}
collect_aa_status() {
    local b
    for b in /usr/sbin/apparmor_status /usr/sbin/aa-status; do
        [[ -x $b ]] && { tmo_tol "$b"; return 0; }
    done
    return 1
}
collect_ps_chronyd() { tmo ps -eo user:32=,args=; }
collect_root_path() {
    # root's login PATH without a PAM session: a login shell with a clean env
    tmo env -i HOME=/root USER=root LOGNAME=root SHELL=/bin/bash TERM=dumb \
        /bin/bash -l -c 'printenv PATH' </dev/null
}
collect_mta_cfg() {
    local b out
    if find_bin postconf; then
        # effective value (postfix defaults to "all"), unlike the PDF's postconf -n
        out=$(tmo "$BIN" inet_interfaces) || return 1
        printf 'postconf: %s\n' "$out"
    elif find_bin exim || find_bin exim4; then
        out=$(tmo "$BIN" -bP local_interfaces) || return 1
        [[ $out == *=* && -n ${out#*=} && ${out#*=} != " " ]] || out="local_interfaces = all"
        printf 'exim: %s\n' "$out"
    elif find_bin sendmail && [[ -r /etc/mail/sendmail.cf ]]; then
        b=$(grep -i 'O DaemonPortOptions=' /etc/mail/sendmail.cf | grep -oP '(?<=Addr=)[^,+]+' | grep -v '^127\.0\.0\.1$')
        printf 'sendmail: %s\n' "$b"
    fi
    return 0
}
# 1.2.1.3 step 1: key files in the standard keyring dirs that are too permissive
collect_apt_keyfiles() {
    local f
    while IFS= read -r -d '' f; do
        stat -Lc '%a	%U	%G	%n' -- "$f"
    done < <(tmo find -L /usr/share/keyrings/ /etc/apt/trusted.gpg.d/ -mount -xdev -type f \
        \( ! -user root -o ! -group root -o -perm /133 \) -name '*gpg' -print0 2>/dev/null)
}
# 6.1.3.1: log files whose mode/owner/group might violate the rules (the benchmark's
# find criteria); the check applies the per-file rules.
collect_logfiles() {
    local f
    while IFS= read -r -d '' f; do
        stat -Lc '%a	%U	%G	%n' -- "$f"
    done < <(slow_tmo find -L /var/log -type f \( -perm /0137 -o ! -user root -o ! -group root \) -print0 2>/dev/null)
}
# 3.1.2: kernel modules that drive wireless interfaces
collect_wireless_modules() {
    local d m
    for d in /sys/class/net/*/wireless; do
        [[ -d $d ]] || continue
        m=$(readlink -f "${d%/wireless}/device/driver/module" 2>/dev/null)
        [[ -n $m ]] && basename -- "$m"
    done
    return 0
}
# 7.2.10 / 7.2.11: dot files and dot directories in the home of every local
# interactive user: user, kind (f|d), mode, owner, group, path.
collect_home_dots() {
    local shells user home shell f kind mode owner grp
    shells=$(awk -F/ '$NF != "nologin" && /^\// {print}' /etc/shells)
    while IFS=: read -r user _ _ _ _ home shell; do
        [[ -n $user && -n $home && -n $shell ]] || continue
        grep -qxF -- "$shell" <<<"$shells" || continue
        [[ -d $home ]] || continue
        printf 'home\t%s\t%s\t%s\n' "$user" "$home" "$(findmnt -no FSTYPE --target "$home" 2>/dev/null)"
        for kind in f d; do
            while IFS= read -r -d '' f; do
                read -r mode owner grp < <(stat -Lc '%a %U %G' -- "$f")
                printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$kind" "$user" "$mode" "$owner" "$grp" "$f"
            done < <(tmo find "$home" -xdev -type "$kind" -name '.*' -print0 2>/dev/null)
        done
    done </etc/passwd
}
# journald/rsyslog evidence for sudo events (5.2.3, read-only variant)
collect_sudo_log() {
    tmo_tol journalctl -t sudo -t sudo-rs -n 5 --no-pager -q 2>/dev/null
    return 0
}

slow_tmo() { timeout -k 3 "$((CHECK_TIMEOUT * ${SLOW_TIMEOUT_FACTOR:-5}))" "$@"; }

# Filesystem types the walks skip: the PDF's list (network, proc, vfat, iso9660, efivarfs,
# selinuxfs, ncpfs) plus the pseudo filesystems that `findmnt -D` hides in the PDF scripts.
WALK_SKIP_FS='nfs|proc|cifs|smb|vfat|iso9660|efivarfs|selinuxfs|ncpfs|sysfs|devtmpfs|devpts|cgroup|cgroup2|securityfs|debugfs|tracefs|configfs|fusectl|bpf|pstore|mqueue|hugetlbfs|autofs|binfmt_misc|rpc_pipefs|nsfs|squashfs|ramfs'

# Mount points a filesystem walk may visit: local filesystems only (7.1.11-7.1.13).
walk_mounts() { # walk_mounts <exclude-fstype-re> <exclude-target-re>
    local line t f
    while IFS= read -r line; do
        [[ $line =~ TARGET=\"([^\"]*)\".*FSTYPE=\"([^\"]*)\" ]] || continue
        t=${BASH_REMATCH[1]} f=${BASH_REMATCH[2]}
        [[ $f =~ ^($1) ]] && continue
        [[ $t =~ ^($2)(/|$) ]] && continue
        printf '%s\n' "$t"
    done < <(findmnt -knP -o TARGET,FSTYPE)
}

collect_fs_world() {
    local m f mode
    local -a prune=(-path '*/containers/storage/*' -o -path '*/containerd/*' -o -path '*/kubelet/*'
        -o -path '/sys/*' -o -path '/snap/*' -o -path '/boot/efi/*')
    while IFS= read -r m; do
        while IFS= read -r -d '' f; do
            [[ -e $f ]] || continue
            if [[ -f $f ]]; then
                printf 'f\t%s\n' "$f"
            elif [[ -d $f ]]; then
                mode=$(stat -Lc '%a' -- "$f")
                (( (8#$mode & 8#1000) == 0 )) && printf 'd\t%s\n' "$f"
            fi
        done < <(slow_tmo find "$m" -mount -xdev \( "${prune[@]}" \) -prune -o \( -type f -o -type d \) -perm -0002 -print0 2>/dev/null)
    done < <(walk_mounts "$WALK_SKIP_FS" '/run|/tmp|/var/tmp')
}
collect_fs_nouser() {
    local m f u g
    local -a prune=(-path '*/containers/storage/*' -o -path '*/containerd/*' -o -path '*/kubelet/*'
        -o -path '/sys/*' -o -path '/snap/*' -o -path '/boot/efi/*')
    while IFS= read -r m; do
        while IFS= read -r -d '' f; do
            [[ -e $f ]] || continue
            IFS=: read -r u g < <(stat -Lc '%U:%G' -- "$f")
            [[ $u == UNKNOWN ]] && printf 'u\t%s\n' "$f"
            [[ $g == UNKNOWN ]] && printf 'g\t%s\n' "$f"
        done < <(slow_tmo find "$m" -mount -xdev \( "${prune[@]}" \) -prune -o \( -type f -o -type d \) \( -nouser -o -nogroup \) -print0 2>/dev/null)
    done < <(walk_mounts "$WALK_SKIP_FS" '/run|/tmp|/var/tmp')
}
collect_fs_suid() {
    local m f mode line t fs o
    while IFS= read -r line; do
        [[ $line =~ TARGET=\"([^\"]*)\".*FSTYPE=\"([^\"]*)\".*OPTIONS=\"([^\"]*)\" ]] || continue
        t=${BASH_REMATCH[1]} fs=${BASH_REMATCH[2]} o=${BASH_REMATCH[3]}
        [[ $fs =~ ^($WALK_SKIP_FS) ]] && continue
        [[ $t == /run/user/* ]] && continue
        [[ ,$o, == *,noexec,* || ,$o, == *,nosuid,* ]] && continue
        while IFS= read -r -d '' f; do
            [[ -e $f ]] || continue
            mode=$(stat -Lc '%a' -- "$f")
            (( 8#$mode & 8#4000 )) && printf 'suid\t%s\n' "$f"
            (( 8#$mode & 8#2000 )) && printf 'sgid\t%s\n' "$f"
        done < <(slow_tmo find "$t" -xdev -type f \( -perm -2000 -o -perm -4000 \) -print0 2>/dev/null)
    done < <(findmnt -knP -o TARGET,SOURCE,FSTYPE,OPTIONS)
}

# ------------------------------------------------------------ file access --
# fstat <path>: file metadata via stat -L (never lstat). Sets S_MODE (octal,
# no leading zero, includes setuid/sticky), S_USER, S_GROUP, S_TYPE (f|d|o).
# In test mode metadata comes from $FACTS_DIR/stat.tsv (path mode user group type);
# paths missing from that map take safe defaults if the fixture file exists.
declare -A STATMAP=()
STATMAP_LOADED=0
_fstat_raw() {
    local p=$1 line t
    S_MODE="" S_USER="" S_GROUP="" S_TYPE="" S_MODE4=""
    if (( FIXTURE_MODE )); then
        if (( ! STATMAP_LOADED )); then
            if [[ -r $FACTS_DIR/stat.tsv ]]; then
                local sp sm su sg st
                while IFS=$'\t' read -r sp sm su sg st; do
                    [[ -z $sp || $sp == \#* ]] && continue
                    STATMAP[$sp]="$sm $su $sg ${st:-f}"
                done <"$FACTS_DIR/stat.tsv"
            fi
            STATMAP_LOADED=1
        fi
        if [[ -n ${STATMAP[$p]+x} ]]; then
            read -r S_MODE S_USER S_GROUP S_TYPE <<<"${STATMAP[$p]}"
            [[ $S_MODE == - ]] && return 1     # explicitly absent
            return 0
        fi
        if [[ -d $R$p ]]; then
            S_MODE=755 S_USER=root S_GROUP=root S_TYPE=d
            return 0
        elif [[ -e $R$p ]]; then
            S_MODE=644 S_USER=root S_GROUP=root S_TYPE=f
            return 0
        fi
        return 1
    fi
    line=$(stat -Lc '%a %U %G %F' -- "$p" 2>/dev/null) || return 1
    read -r S_MODE S_USER S_GROUP t <<<"$line"
    case $t in
        *directory*) S_TYPE=d ;;
        *regular*) S_TYPE=f ;;
        *) S_TYPE=o ;;
    esac
    return 0
}

fstat() {
    _fstat_raw "$1" || return 1
    printf -v S_MODE4 '%04o' "$((8#$S_MODE))"
}

# fexists <path> (honours test-mode absent entries)
fexists() { fstat "$1"; }

# --------------------------------------------------------- parsed facts ----
declare -A PKG_STATE=() PKG_VER=()
need_dpkg() {
    [[ -n ${LOADED_dpkg-} ]] && return 0
    _need_fact dpkg || return 1
    local p s v
    while IFS=$'\t' read -r p s v; do
        [[ -n $p ]] || continue
        PKG_STATE[$p]=$s PKG_VER[$p]=$v
    done <"$FACT_FILE"
    LOADED_dpkg=1
}
pkg_installed() { [[ ${PKG_STATE[$1]-} == installed ]]; }

declare -A UNIT_FILE_STATE=() UNIT_ACTIVE=() UNIT_LOAD=()
need_unit_files() {
    [[ -n ${LOADED_unit_files-} ]] && return 0
    _need_fact unit_files || return 1
    local u s rest
    while read -r u s rest; do
        [[ -n $u ]] && UNIT_FILE_STATE[$u]=$s
    done <"$FACT_FILE"
    LOADED_unit_files=1
}
need_units() {
    need_unit_files || return 1
    [[ -n ${LOADED_units-} ]] && return 0
    _need_fact units_all || return 1
    local u load act rest
    while read -r u load act rest; do
        [[ $u == ●* ]] && { read -r u load act rest <<<"$load $act $rest"; }
        [[ -n $u ]] && { UNIT_LOAD[$u]=$load; UNIT_ACTIVE[$u]=$act; }
    done <"$FACT_FILE"
    LOADED_units=1
}
unit_is_enabled() { [[ ${UNIT_FILE_STATE[$1]-} == enabled* ]]; }
unit_is_active() { [[ ${UNIT_ACTIVE[$1]-} == active ]]; }
unit_describe() { # -> REPLY "enabled-state/active-state"
    REPLY="${UNIT_FILE_STATE[$1]:-not-found}/${UNIT_ACTIVE[$1]:-inactive}"
}

declare -A MNT_OPTS=() MNT_FSTYPE=() MNT_SRC=()
MNT_TARGETS=()
need_mounts() {
    [[ -n ${LOADED_mounts-} ]] && return 0
    _need_fact mounts || return 1
    local line
    while IFS= read -r line; do
        if [[ $line =~ TARGET=\"([^\"]*)\"\ SOURCE=\"([^\"]*)\"\ FSTYPE=\"([^\"]*)\"\ OPTIONS=\"([^\"]*)\" ]]; then
            MNT_OPTS[${BASH_REMATCH[1]}]=${BASH_REMATCH[4]}
            MNT_FSTYPE[${BASH_REMATCH[1]}]=${BASH_REMATCH[3]}
            MNT_SRC[${BASH_REMATCH[1]}]=${BASH_REMATCH[2]}
            MNT_TARGETS+=("${BASH_REMATCH[1]}")
        fi
    done <"$FACT_FILE"
    LOADED_mounts=1
}
# mount_for_path <path> -> REPLY = fstype of the mount containing the path
mount_fstype_for() {
    local p=$1 best="" t
    for t in "${MNT_TARGETS[@]}"; do
        if [[ $p == "$t" || $p == "${t%/}"/* ]]; then
            (( ${#t} > ${#best} )) && best=$t
        fi
    done
    REPLY=${MNT_FSTYPE[$best]-}
}

declare -A SYSCTL_RUN=() SYSCTL_PERSIST=() SYSCTL_PERSIST_FILE=() SYSCTL_ALL=() UFW_SYSCTL=()
sysctl_key() { # normalise a/b/c -> a.b.c
    REPLY=${1//\//.}
}
need_sysctl() {
    [[ -n ${LOADED_sysctl-} ]] && return 0
    _need_fact sysctl_running || return 1
    local k v line file
    while IFS= read -r line; do
        [[ $line =~ ^([^[:space:]=]+)[[:space:]]*=[[:space:]]*(.*)$ ]] || continue
        SYSCTL_RUN[${BASH_REMATCH[1]}]=${BASH_REMATCH[2]}
    done <"$FACT_FILE"
    _need_fact sysctl_cat || return 1
    file=""
    while IFS= read -r line; do
        if [[ $line =~ ^[[:space:]]*#[[:space:]]*(/[^#[:space:]]+\.conf)$ ]]; then
            file=${BASH_REMATCH[1]}
            continue
        fi
        [[ $line =~ ^[[:space:]]*[#\;] ]] && continue
        if [[ $line =~ ^[[:space:]]*-?([^[:space:]=]+)[[:space:]]*=[[:space:]]*([^[:space:]].*)$ ]]; then
            sysctl_key "${BASH_REMATCH[1]}"
            k=$REPLY
            v=${BASH_REMATCH[2]}
            v=${v%"${v##*[![:space:]]}"}
            SYSCTL_PERSIST[$k]=$v
            SYSCTL_PERSIST_FILE[$k]=$file
            SYSCTL_ALL[$k]+="${file}: $v"$'\n'
        fi
    done <"$FACT_FILE"
    # ufw applies its own sysctl file when it is enabled; it is loaded last.
    local ufwconf=$R/etc/ufw/ufw.conf ufwdef=$R/etc/default/ufw ufwsys="/etc/ufw/sysctl.conf" l
    if [[ -r $ufwdef ]]; then
        l=$(grep -Poi '^\s*IPT_SYSCTL=\K\S+' -- "$ufwdef" | tail -n1)
        l=${l//\"/}
        [[ -n $l ]] && ufwsys=$l
    fi
    UFW_SYSCTL_FILE=$ufwsys
    UFW_ENABLED=0
    [[ -r $ufwconf ]] && grep -Pqi '^\s*ENABLED\s*=\s*yes\b' -- "$ufwconf" && UFW_ENABLED=1
    if (( UFW_ENABLED )) && [[ -r $R$ufwsys ]]; then
        while IFS= read -r line; do
            [[ $line =~ ^[[:space:]]*[#\;] ]] && continue
            if [[ $line =~ ^[[:space:]]*([^[:space:]=]+)[[:space:]]*=[[:space:]]*([^[:space:]]+) ]]; then
                sysctl_key "${BASH_REMATCH[1]}"
                UFW_SYSCTL[$REPLY]=${BASH_REMATCH[2]}
            fi
        done <"$R$ufwsys"
    fi
    LOADED_sysctl=1
}

declare -A SSHD=()
need_sshd() {
    [[ -n ${LOADED_sshd-} ]] && return 0
    _need_fact sshd_T || return 1
    local k v line
    while IFS= read -r line; do
        k=${line%% *}
        v=${line#* }
        [[ $line == *" "* ]] || v=""
        SSHD["base:$k"]=$v
        SSHD["baseall:$k"]+="$v"$'\n'
    done <"$FACT_FILE"
    SSHD_HAS_MATCH=0
    if grep -Pqsi '^\s*Match\s+(User|Group|Host|LocalAddress|LocalPort|Address)\b' -- "$R/etc/ssh/sshd_config" "$R"/etc/ssh/sshd_config.d/*.conf 2>/dev/null; then
        SSHD_HAS_MATCH=1
        if fact sshd_T_C; then
            while IFS= read -r line; do
                k=${line%% *}
                v=${line#* }
                [[ $line == *" "* ]] || v=""
                SSHD["match:$k"]=$v
            done <"$FACT_FILE"
        fi
    fi
    LOADED_sshd=1
}

declare -A MOD_BLACKLIST=() MOD_INSTALL=() LSMOD=()
need_modprobe() {
    [[ -n ${LOADED_modprobe-} ]] && return 0
    _need_fact modprobe_cfg || return 1
    local kw a b rest
    while read -r kw a b rest; do
        a=${a//-/_}
        case $kw in
            blacklist) MOD_BLACKLIST[$a]=1 ;;
            install) MOD_INSTALL[$a]="$b${rest:+ $rest}" ;;
        esac
    done <"$FACT_FILE"
    LOADED_modprobe=1
}
need_lsmod() {
    [[ -n ${LOADED_lsmod-} ]] && return 0
    _need_fact lsmod || return 1
    local m rest
    while read -r m rest; do
        [[ $m == Module ]] && continue
        LSMOD[${m//-/_}]=1
    done <"$FACT_FILE"
    LOADED_lsmod=1
}
need_kmod() { _need_fact kmod_files; }
need_ss() { _need_fact ss_listen; }
need_ufw() { _need_fact ufw_status; }
need_aptcfg() { _need_fact apt_config; }
need_aptpol() { _need_fact apt_policy; }

# ------------------------------------------------- systemd cat-config -------
# catcfg_get <name> <section> <key>
#  Sets CC_VALUE/CC_FILE/CC_DEFAULT/CC_ALL from `systemd-analyze cat-config`.
#  The last uncommented assignment wins. CC_DEFAULT holds the first commented
#  "#Key=Value" default in the section, as the benchmark's scripts read it.
catcfg_get() {
    local name=$1 section=$2 key=$3 line file="" cur="" k v
    CC_VALUE="" CC_FILE="" CC_DEFAULT="" CC_ALL=""
    _need_fact catcfg "$name" || return 1
    while IFS= read -r line; do
        if [[ $line =~ ^[[:space:]]*#[[:space:]]*(/[^#[:space:]]+\.conf)[[:space:]]*$ ]]; then
            file=${BASH_REMATCH[1]}
            continue
        fi
        if [[ $line =~ ^[[:space:]]*\[([^]]+)\][[:space:]]*$ ]]; then
            cur=${BASH_REMATCH[1]}
            continue
        fi
        [[ $cur == "$section" ]] || continue
        if [[ $line =~ ^[[:space:]]*([A-Za-z0-9_]+)[[:space:]]*=[[:space:]]*(.*)$ ]]; then
            k=${BASH_REMATCH[1]} v=${BASH_REMATCH[2]}
            if [[ ${k,,} == "${key,,}" ]]; then
                v=${v%%#*}
                v=${v%"${v##*[![:space:]]}"}
                CC_VALUE=$v CC_FILE=$file
                CC_ALL+="$file: $key=$v"$'\n'
            fi
        elif [[ -z $CC_DEFAULT && $line =~ ^[[:space:]]*#[[:space:]]*([A-Za-z0-9_]+)[[:space:]]*=[[:space:]]*(.*)$ ]]; then
            if [[ ${BASH_REMATCH[1],,} == "${key,,}" ]]; then
                CC_DEFAULT=${BASH_REMATCH[2]}
                CC_DEFAULT=${CC_DEFAULT%"${CC_DEFAULT##*[![:space:]]}"}
            fi
        fi
    done <"$FACT_FILE"
    return 0
}

# --------------------------------------------------------------- misc -------
os_release_get() { # os_release_get KEY -> REPLY (no sourcing)
    local line v
    REPLY=""
    [[ -r $R/etc/os-release ]] || return 1
    while IFS= read -r line; do
        if [[ $line =~ ^$1=(.*)$ ]]; then
            v=${BASH_REMATCH[1]}
            v=${v#\"}
            v=${v%\"}
            REPLY=$v
            return 0
        fi
    done <"$R/etc/os-release"
    return 1
}

# ==== lib/applicability.sh ====
# lib/applicability.sh - derived flags and the applies_if evaluator.
#
# Flags are computed lazily on first use so that `--only 5.1.7` does not collect
# unrelated facts. A control whose condition is false is reported as N/A with the
# reason in the evidence.
# shellcheck disable=SC2034

declare -A FLAG=()
APPLIES_WHY=""

flag_get() { # flag_get NAME -> REPLY (empty + return 1 when it cannot be derived)
    local n=$1
    if [[ -z ${FLAG[$n]+x} ]]; then
        if ! declare -F "flag_$n" >/dev/null; then
            REPLY=""
            return 1
        fi
        "flag_$n" || { FLAG[$n]="?"; }
    fi
    REPLY=${FLAG[$n]}
    [[ $REPLY != "?" ]]
}

flag_TIME_DAEMON() {
    local v=${SITE[TIME_DAEMON]:-auto} out=""
    if [[ $v != auto ]]; then
        FLAG[TIME_DAEMON]=$v
        return 0
    fi
    need_units || return 1
    if unit_is_enabled chrony.service || unit_is_active chrony.service; then out=chrony; fi
    if unit_is_enabled systemd-timesyncd.service || unit_is_active systemd-timesyncd.service; then
        out=${out:+$out+}timesyncd
    fi
    FLAG[TIME_DAEMON]=${out:-none}
}

flag_LOGGER() {
    local v=${SITE[LOGGER]:-auto}
    if [[ $v != auto ]]; then
        FLAG[LOGGER]=$v
        return 0
    fi
    need_dpkg && need_units || return 1
    if pkg_installed rsyslog && unit_is_active rsyslog.service; then
        FLAG[LOGGER]=rsyslog
    else
        FLAG[LOGGER]=journald
    fi
}

flag_HAS_GDM() { need_dpkg || return 1; pkg_installed gdm3 && FLAG[HAS_GDM]=1 || FLAG[HAS_GDM]=0; }
flag_HAS_CRON() { need_dpkg || return 1; pkg_installed cron && FLAG[HAS_CRON]=1 || FLAG[HAS_CRON]=0; }
flag_HAS_AT() { need_dpkg || return 1; pkg_installed at && FLAG[HAS_AT]=1 || FLAG[HAS_AT]=0; }
flag_HAS_COREDUMP() {
    need_dpkg || return 1
    pkg_installed systemd-coredump && FLAG[HAS_COREDUMP]=1 || FLAG[HAS_COREDUMP]=0
}
flag_HAS_MTA() {
    need_dpkg || return 1
    local p
    FLAG[HAS_MTA]=0
    for p in postfix exim4 exim4-daemon-light exim4-daemon-heavy sendmail; do
        pkg_installed "$p" && FLAG[HAS_MTA]=1
    done
    return 0
}

# IPv6 per 3.1.1: not enabled when /sys/module/ipv6/parameters/disable is not 0,
# or when both disable_ipv6 sysctls are 1.
flag_IPV6_ENABLED() {
    local en=1
    if ! grep -Pqs '^\s*0\b' -- "$R/sys/module/ipv6/parameters/disable"; then en=0; fi
    if need_sysctl; then
        if [[ ${SYSCTL_RUN[net.ipv6.conf.all.disable_ipv6]-} == 1 && ${SYSCTL_RUN[net.ipv6.conf.default.disable_ipv6]-} == 1 ]]; then
            en=0
        fi
    fi
    FLAG[IPV6_ENABLED]=$en
}

# applies <applies_if>: comma separated AND of NAME=value | NAME~value (contains)
# | NAME!=value. Returns 0 when the control applies. Sets APPLIES_WHY on false.
applies() {
    local cond=$1 c n op v
    local -a conds
    APPLIES_WHY=""
    [[ -z $cond || $cond == "-" ]] && return 0
    IFS=',' read -ra conds <<<"$cond"
    for c in "${conds[@]}"; do
        if [[ $c =~ ^([A-Z0-9_]+)(!=|=|~)(.*)$ ]]; then
            n=${BASH_REMATCH[1]} op=${BASH_REMATCH[2]} v=${BASH_REMATCH[3]}
        else
            APPLIES_WHY="invalid applies_if condition '$c'"
            return 2
        fi
        if ! flag_get "$n"; then
            APPLIES_WHY="cannot derive applicability flag $n"
            return 2
        fi
        case $op in
            =) [[ $REPLY == "$v" ]] || { APPLIES_WHY="condition $c is false ($n=$REPLY)"; return 1; } ;;
            '!=') [[ $REPLY != "$v" ]] || { APPLIES_WHY="condition $c is false ($n=$REPLY)"; return 1; } ;;
            '~') [[ $REPLY == *"$v"* ]] || { APPLIES_WHY="condition $c is false ($n=$REPLY)"; return 1; } ;;
        esac
    done
    return 0
}

# ==== lib/checks_generic.sh ====
# lib/checks_generic.sh - the 15 generic check types.
#
# Contract: chk_<type> <ID> reads its parameters from the global P array (set from
# the catalog row) and the parsed facts, and ends with exactly one `result` call.
# No command is run here; only fact accessors from facts.sh are used.
# shellcheck disable=SC2034,SC2154

# ------------------------------------------------------------- helpers ----
pget() { REPLY=${P[$1]-${2-}}; }

# expand_glob <pattern>: GLOB = existing paths (without the test root prefix)
expand_glob() {
    local pat=$1 f
    GLOB=()
    if [[ $pat != *[*?[]* ]]; then
        fexists "$pat" && GLOB=("$pat")
        return 0
    fi
    shopt -s nullglob
    for f in $R$pat; do
        GLOB+=("${f#"$R"}")
    done
    shopt -u nullglob
}

# perm_eval <path> <max-mode> <owners a|b> <groups a|b>
# Appends to PERM_OK / PERM_BAD. Returns 1 when the path does not exist.
perm_eval() {
    local p=$1 max=$2 owners=$3 groups=$4 ex bad=""
    fstat "$p" || return 1
    mode4 "$max"
    local max4=$M4
    oct_excess "$S_MODE" "$max" || bad="mode $S_MODE4 grants $OCT_EX beyond allowed $max4"
    list_has "$owners" "$S_USER" || bad+="${bad:+, }owner $S_USER, expected ${owners//|/ or }"
    list_has "$groups" "$S_GROUP" || bad+="${bad:+, }group $S_GROUP, expected ${groups//|/ or }"
    if [[ -n $bad ]]; then
        PERM_BAD+=("$p: $bad")
    else
        PERM_OK+=("$p: mode $S_MODE4 owner $S_USER group $S_GROUP (max $max4, ${owners//|/ or }:${groups//|/ or })")
    fi
    return 0
}

# strip one pair of surrounding double quotes
unquote() { REPLY=${1#\"}; REPLY=${REPLY%\"}; }

# val_ok <op> <expected> <actual>   (numeric and string comparisons)
val_ok() {
    local op=$1 exp=$2 act=$3
    unquote "$act"
    act=$REPLY
    case $op in
        eq) [[ ${act,,} == "${exp,,}" ]] ;;
        ne) [[ ${act,,} != "${exp,,}" ]] ;;
        oneof) list_has "${exp,,}" "${act,,}" ;;
        le) is_int "$act" && (( act <= exp )) ;;
        lt) is_int "$act" && (( act < exp )) ;;
        ge) is_int "$act" && (( act >= exp )) ;;
        gt) is_int "$act" && (( act > exp )) ;;
        range) is_int "$act" && (( act >= ${exp%-*} && act <= ${exp#*-} )) ;;
        range1) is_int "$act" && (( act >= 1 && act <= exp )) ;;
        zero_or_ge) is_int "$act" && (( act == 0 || act >= exp )) ;;
        set) [[ -n $act ]] ;;
        *) return 2 ;;
    esac
}

# op_text <op> <expected> -> REPLY, a readable form of a comparison
op_text() {
    case $1 in
        eq) REPLY="$2" ;;
        ne) REPLY="anything but $2" ;;
        oneof) REPLY="one of ${2//,/, }" ;;
        le) REPLY="$2 or less" ;;
        lt) REPLY="less than $2" ;;
        ge) REPLY="$2 or more" ;;
        gt) REPLY="greater than $2" ;;
        range) REPLY="${2%-*} to ${2#*-}" ;;
        range1) REPLY="1 to $2" ;;
        zero_or_ge) REPLY="0 (never) or $2 or more" ;;
        set) REPLY="a value" ;;
        flag) REPLY="the option present" ;;
        *) REPLY="$1 $2" ;;
    esac
}

# ---------------------------------------------------------------- sysctl ---
chk_sysctl() {
    local id=$1 key=${P[key]-} vals=${P[values]:-${P[value]-}} run persisted src exp
    local -a good=() bad=()
    need sysctl || return
    exp=${vals//,/ or }
    if [[ -z ${SYSCTL_RUN[$key]+x} ]]; then
        bad+=("$key: not present in the running kernel (sysctl -a), expected $exp")
    else
        run=${SYSCTL_RUN[$key]}
        run=${run%"${run##*[![:space:]]}"}
        run=${run//[[:space:]]/ }
        if list_has "${vals// /,}" "$run"; then
            good+=("$key: running=$run, expected $exp")
        else
            bad+=("$key: running=$run, expected $exp")
        fi
    fi
    if [[ -n ${UFW_SYSCTL[$key]+x} ]]; then
        persisted=${UFW_SYSCTL[$key]} src="$UFW_SYSCTL_FILE (ufw is enabled and applies it last)"
    elif [[ -n ${SYSCTL_PERSIST[$key]+x} ]]; then
        persisted=${SYSCTL_PERSIST[$key]} src=${SYSCTL_PERSIST_FILE[$key]}
    else
        persisted="" src=""
    fi
    if [[ -z $persisted ]]; then
        bad+=("$key: persisted=not set in any file read by systemd-sysctl (a reboot would reset it), expected $exp")
    elif list_has "${vals// /,}" "$persisted"; then
        good+=("$key: persisted=$persisted ($src), expected $exp")
    else
        bad+=("$key: persisted=$persisted ($src), expected $exp")
        [[ -n ${SYSCTL_ALL[$key]-} ]] && bad+=("all assignments seen by systemd-sysctl (last wins): ${SYSCTL_ALL[$key]//$'\n'/; }")
    fi
    if (( ${#bad[@]} )); then result "$id" FAIL "${bad[@]}" "${good[@]}"; else result "$id" PASS "${good[@]}"; fi
}

# ------------------------------------------------------------- file_perm ---
chk_file_perm() {
    local id=$1 spec=${P[path]-} max=${P[mode]-} owners=${P[owner]:-root} groups=${P[group]:-root}
    local missing=${P[missing]:-fail} one found=0
    local -a paths ev=() PERM_OK=() PERM_BAD=() lst
    case ${P[dyn]-} in
        pam_motd) dyn_pam_motd_paths ;;
        sshd_banner) dyn_sshd_banner_paths ;;
        *) IFS=',' read -ra paths <<<"$spec" ;;
    esac
    if [[ -n ${P[dyn]-} ]]; then
        paths=("${DYN_PATHS[@]}")
        if (( ${#paths[@]} == 0 )); then
            result "$id" PASS "${DYN_NONE_MSG:-no file configured; nothing to check}"
            return
        fi
    fi
    for one in "${paths[@]}"; do
        expand_glob "$one"
        lst=("${GLOB[@]}")
        if (( ${#lst[@]} == 0 )); then
            ev+=("$one: does not exist")
            if [[ $missing == fail ]]; then PERM_BAD+=("$one: does not exist"); fi
            continue
        fi
        for found in "${lst[@]}"; do
            perm_eval "$found" "$max" "$owners" "$groups"
        done
    done
    if (( ${#PERM_BAD[@]} )); then
        result "$id" FAIL "${PERM_BAD[@]}" "${PERM_OK[@]}"
    elif (( ${#PERM_OK[@]} )); then
        result "$id" PASS "${PERM_OK[@]}" "${ev[@]}"
    elif [[ $missing == na ]]; then
        result "$id" N/A "${ev[@]}"
    else
        result "$id" PASS "${ev[@]}" "(nothing to check; benchmark treats a missing path as passing)"
    fi
}

chk_file_perm_glob() {
    local id=$1
    case ${P[source]-glob} in
        sshd_hostkey) chk_sshd_hostkeys "$id" ;;
        *)
            P[path]="${P[dir]%/}/${P[pattern]:-*}"
            P[missing]=${P[missing]:-pass}
            chk_file_perm "$id"
            ;;
    esac
}

# 5.1.3 / 5.1.4: host key files listed by sshd -T
chk_sshd_hostkeys() {
    local id=$1 k suffix=${P[suffix]-} max=${P[mode]-} line
    local -a keys=() PERM_OK=() PERM_BAD=() ev=()
    need sshd || return
    while IFS= read -r line; do
        [[ -n $line ]] && keys+=("$line$suffix")
    done <<<"${SSHD[baseall:hostkey]-}"
    if (( ${#keys[@]} == 0 )); then
        result "$id" PASS "sshd -T lists no hostkey entries; nothing to check"
        return
    fi
    for k in "${keys[@]}"; do
        if ! perm_eval "$k" "$max" "${P[owner]:-root}" "${P[group]:-root}"; then
            ev+=("$k: listed by sshd -T but does not exist (not checked)")
        fi
    done
    if (( ${#PERM_BAD[@]} )); then
        result "$id" FAIL "${PERM_BAD[@]}" "${PERM_OK[@]}"
    else
        result "$id" PASS "${PERM_OK[@]}" "${ev[@]}"
    fi
}

# dynamic path sets for 1.6.9 / 1.6.10
dyn_pam_motd_paths() {
    DYN_PATHS=() DYN_NONE_MSG="no motd= argument is set on a pam_motd line in /etc/pam.d"
    local f m
    shopt -s nullglob
    for f in $R/etc/pam.d/*; do
        [[ -f $f ]] || continue
        while IFS= read -r m; do
            m=${m#\"}; m=${m%\"}; m=${m#\'}; m=${m%\'}
            [[ -n $m ]] && DYN_PATHS+=("$m")
        done < <(grep -hPo 'motd=\K\S+' -- "$f" 2>/dev/null)
    done
    shopt -u nullglob
    if (( ${#DYN_PATHS[@]} )); then
        mapfile -t DYN_PATHS < <(printf '%s\n' "${DYN_PATHS[@]}" | LC_ALL=C sort -u)
    fi
}
dyn_sshd_banner_paths() {
    DYN_PATHS=() DYN_NONE_MSG="sshd -T shows no Banner file (rule 1.6.5 covers the missing directive)"
    need sshd || return
    local b=${SSHD[base:banner]-}
    if [[ $b == /* ]]; then DYN_PATHS=("$b"); fi
}

# ------------------------------------------------------- svc_not_in_use ----
# pkg_match_installed <pattern-list>: sets PKG_HITS to installed packages that
# match any entry (entries may end in *).
pkg_match_installed() {
    local list=$1 e p
    PKG_HITS=()
    local -a ents
    IFS=',' read -ra ents <<<"$list"
    for e in "${ents[@]}"; do
        [[ -z $e ]] && continue
        if [[ $e == *'*' ]]; then
            for p in "${!PKG_STATE[@]}"; do
                [[ $p == ${e} && ${PKG_STATE[$p]} == installed ]] && PKG_HITS+=("$p")
            done
        elif pkg_installed "$e"; then
            PKG_HITS+=("$e")
        fi
    done
}

chk_svc_not_in_use() {
    local id=$1 pkgs=${P[pkgs]-} units=${P[units]-} u d
    local -a ev=() act=() ents
    need dpkg units || return
    pkg_match_installed "$pkgs"
    if [[ -n $pkgs ]] && (( ${#PKG_HITS[@]} == 0 )); then
        result "$id" PASS "none of the packages (${pkgs//,/, }) is installed"
        return
    fi
    IFS=',' read -ra ents <<<"$units"
    for u in "${ents[@]}"; do
        [[ -z $u ]] && continue
        unit_describe "$u"
        d=$REPLY
        if unit_is_enabled "$u" || unit_is_active "$u"; then
            act+=("$u: $d (enabled-state/active-state), expected neither enabled nor active")
        else
            ev+=("$u: $d (not enabled, not active)")
        fi
    done
    local pk="no package"
    (( ${#PKG_HITS[@]} )) && pk="installed: ${PKG_HITS[*]}"
    if (( ${#act[@]} )); then
        result "$id" FAIL "$pk" "${act[@]}" "${ev[@]}"
    else
        result "$id" PASS "$pk; the service units are neither enabled nor active" "${ev[@]}"
    fi
}

# -------------------------------------------------------- svc_enabled_active
chk_svc_enabled_active() {
    local id=$1 want=${P[need]:-enabled,active} spec=${P[unit]-} u pick="" d
    local -a ents
    need units || return
    IFS='|' read -ra ents <<<"$spec"
    for u in "${ents[@]}"; do
        if [[ -n ${UNIT_FILE_STATE[$u]+x} || -n ${UNIT_ACTIVE[$u]+x} ]]; then pick=$u; break; fi
    done
    [[ -n $pick ]] || pick=${ents[0]}
    unit_describe "$pick"
    d=$REPLY
    local bad=0
    list_has "$want" enabled && ! unit_is_enabled "$pick" && bad=1
    list_has "$want" active && ! unit_is_active "$pick" && bad=1
    if (( bad )); then
        result "$id" FAIL "$pick: ${d} (enabled-state/active-state), expected ${want//,/ and }"
    else
        result "$id" PASS "$pick: ${d} (enabled-state/active-state), expected ${want//,/ and }"
    fi
}

# --------------------------------------------------------------- sshd ------
# Words the benchmark calls weak, per 5.1.7 / 5.1.13 / 5.1.17.
sshd_value() { # sshd_value <ctx> <key> -> REPLY (empty + rc 1 when absent)
    if [[ -n ${SSHD["$1:$2"]+x} ]]; then REPLY=${SSHD["$1:$2"]}; return 0; fi
    REPLY=""
    return 1
}

banner_re() {
    os_release_get ID
    local osid=${REPLY:-ubuntu}
    BANNER_RE='(\\v|\\r|\\m|\\s|\b'"${osid//\"/}"'\b)'
}

# sshd_rule <ctx> <key> <op> <value>; appends to SR_OK / SR_BAD
sshd_rule() {
    local ctx=$1 key=$2 op=$3 exp=$4 v tok a b c
    local label="$key"
    [[ $ctx == match ]] && label="$key (Match evaluated for user=root,host=localhost,addr=127.0.0.1)"
    if ! sshd_value "$ctx" "$key"; then
        SR_BAD+=("$label: not reported by sshd -T")
        return
    fi
    v=$REPLY
    unquote "$v"
    v=$REPLY
    case $op in
        none_of)
            local -a toks weak
            IFS=',' read -ra toks <<<"$v"
            IFS=',' read -ra weak <<<"$exp"
            local hits=()
            for tok in "${toks[@]}"; do
                for a in "${weak[@]}"; do
                    [[ ${tok,,} == "${a,,}" ]] && hits+=("$tok")
                done
            done
            if (( ${#hits[@]} )); then
                SR_BAD+=("$label: weak entries in use: ${hits[*]}")
            else
                SR_OK+=("$label: no weak entries (value: $v)")
            fi
            ;;
        maxstartups)
            IFS=: read -r a b c <<<"$v"
            local ea eb ec
            IFS=: read -r ea eb ec <<<"$exp"
            if is_int "$a" && (( a <= ea )) && { [[ -z $b ]] || { is_int "$b" && (( b <= eb )); }; } && { [[ -z $c ]] || { is_int "$c" && (( c <= ec )); }; }; then
                SR_OK+=("$label: $v, expected $exp or more restrictive")
            else
                SR_BAD+=("$label: $v, expected $exp or more restrictive")
            fi
            ;;
        *)
            if val_ok "$op" "$exp" "$v"; then
                op_text "$op" "$exp"; SR_OK+=("$label: $v, expected $REPLY")
            else
                op_text "$op" "$exp"; SR_BAD+=("$label: $v, expected $REPLY")
            fi
            ;;
    esac
}

chk_sshd_param() {
    local id=$1 ctx sfx rk rop rv
    local -a SR_OK=() SR_BAD=() ctxs=(base)
    need sshd || return
    (( SSHD_HAS_MATCH )) && [[ -n ${SSHD[match:permitrootlogin]+x} ]] && ctxs+=(match)
    case ${P[op]-} in
        anyset)
            local k found=0 shown=""
            local -a ks
            IFS=',' read -ra ks <<<"${P[key]-}"
            for k in "${ks[@]}"; do
                if [[ -n ${SSHD[base:$k]-} ]]; then found=1; shown+="$k ${SSHD[base:$k]}; "; fi
            done
            if (( found )); then
                result "$id" PASS "access directive set: ${shown%; }" "review the lists against site policy"
            else
                result "$id" FAIL "none of ${P[key]//,/, } is set in the effective sshd configuration, expected at least one"
            fi
            return
            ;;
        banner)
            sshd_banner_rule
            ;;
        *)
            for sfx in "" 2 3; do
                rk=${P[key$sfx]-}
                [[ -z $rk ]] && continue
                rop=${P[op$sfx]} rv=${P[value$sfx]-}
                for ctx in "${ctxs[@]}"; do sshd_rule "$ctx" "$rk" "$rop" "$rv"; done
            done
            ;;
    esac
    # 5.1.19: MaxSessions must also not exceed the limit in the config files
    if [[ ${P[key]-} == maxsessions ]]; then
        local f hit
        for f in "$R/etc/ssh/sshd_config" "$R"/etc/ssh/sshd_config.d/*.conf; do
            [[ -r $f ]] || continue
            hit=$(grep -Pio -- '^\s*MaxSessions\s+"?\K[0-9]+' "$f" | awk -v max="${P[value]-}" '$1+0>max+0')
            [[ -n $hit ]] && SR_BAD+=("${f#"$R"}: MaxSessions $hit exceeds ${P[value]-}")
        done
    fi
    if (( ${#SR_BAD[@]} )); then
        result "$id" FAIL "${SR_BAD[@]}" "${SR_OK[@]}"
    else
        result "$id" PASS "${SR_OK[@]}"
    fi
}

# 1.6.5 / 5.1.6: Banner set, file exists, no OS information in it
sshd_banner_rule() {
    local ctx b hits
    banner_re
    for ctx in base; do
        sshd_value "$ctx" banner || { SR_BAD+=("banner: not reported by sshd -T"); continue; }
        b=$REPLY
        if [[ $b != /* ]]; then
            SR_BAD+=("banner: '${b:-unset}', expected a file path such as /etc/issue.net")
            continue
        fi
        if [[ ! -r $R$b ]]; then
            SR_BAD+=("banner: file $b is not readable or does not exist")
            continue
        fi
        hits=$(grep -Pi -- "$BANNER_RE" "$R$b" | head -n 3)
        if [[ -n $hits ]]; then
            SR_BAD+=("banner file $b contains OS information or escape codes (\\m \\r \\s \\v or the OS name): $hits")
        else
            SR_OK+=("banner $b: set, no OS information; content must still match site policy")
        fi
        if [[ -n ${SITE[BANNER_FILE]-} && -r $R${SITE[BANNER_FILE]} ]]; then
            if cmp -s -- "$R$b" "$R${SITE[BANNER_FILE]}"; then
                SR_OK+=("banner $b matches site banner ${SITE[BANNER_FILE]}")
            else
                SR_BAD+=("banner $b differs from the site banner ${SITE[BANNER_FILE]}")
            fi
        fi
    done
}

# --------------------------------------------------------------- mounts ----
chk_mount_opt() {
    local id=$1 path=${P[path]-} opt=${P[opt]-} o
    need mounts || return
    if [[ -z ${MNT_OPTS[$path]+x} ]]; then
        result "$id" N/A "$path is not a separate mount point; the benchmark applies this only to a separate partition"
        return
    fi
    o=${MNT_OPTS[$path]}
    if [[ ,$o, == *,"$opt",* ]]; then
        result "$id" PASS "$path (${MNT_FSTYPE[$path]}): options $o include $opt"
    else
        result "$id" FAIL "$path (${MNT_FSTYPE[$path]}): options $o do not include $opt"
    fi
}

chk_mount_tmpfs_or_separate() {
    local id=$1 path=${P[path]-} unit=${P[unit]-} st
    local -a ev=()
    need mounts || return
    if [[ -z ${MNT_OPTS[$path]+x} ]]; then
        result "$id" FAIL "$path is not a mount point (neither tmpfs nor a separate partition)"
        return
    fi
    ev+=("$path is mounted: ${MNT_SRC[$path]} (${MNT_FSTYPE[$path]}) ${MNT_OPTS[$path]}")
    if [[ -n $unit ]]; then
        need unit_files || return
        st=${UNIT_FILE_STATE[$unit]-not-listed}
        case $st in
            masked|masked-runtime|disabled)
                result "$id" FAIL "${ev[@]}" "$unit is $st; systemd would not mount $path at boot"
                return ;;
        esac
        ev+=("$unit unit state: $st (not masked or disabled)")
    fi
    result "$id" PASS "${ev[@]}"
}

# ------------------------------------------------------ kmod_unavailable ---
chk_kmod_unavailable() {
    local id=$1 name=${P[name]-} dir=${P[dir]-} n
    local -a ev=()
    need kmod modprobe lsmod || return
    n=${name//-/_}
    if ! grep -qs -- "/kernel/$dir/" "$FACTS_DIR/kmod_files"; then
        result "$id" PASS "no kernel/$dir module directory under /usr/lib/modules: $name is built in or absent"
        return
    fi
    ev+=("module files for $name exist under kernel/$dir; checking that it is not loaded and not loadable")
    local bad=0
    if [[ -n ${LSMOD[$n]+x} ]]; then
        ev+=("!$name is currently loaded (lsmod), expected not loaded"); bad=1
    else
        ev+=("$name is not loaded (lsmod)")
    fi
    if [[ -n ${MOD_BLACKLIST[$n]+x} ]]; then
        ev+=("blacklist $n is configured")
    else
        ev+=("!missing 'blacklist $n' in modprobe configuration"); bad=1
    fi
    local inst=${MOD_INSTALL[$n]-}
    if [[ $inst == /bin/false || $inst == /bin/true ]]; then
        ev+=("install $n $inst is configured")
    else
        ev+=("!missing 'install $n /bin/false' (or /bin/true) in modprobe configuration${inst:+; found: install $n $inst}"); bad=1
    fi
    result "$id" "$( (( bad )) && echo FAIL || echo PASS)" "${ev[@]}"
}

# ----------------------------------------------------------- packages ------
chk_pkg_absent() {
    local id=$1
    need dpkg || return
    pkg_match_installed "${P[pkgs]-}"
    if (( ${#PKG_HITS[@]} )); then
        result "$id" FAIL "installed: ${PKG_HITS[*]}, expected none of ${P[pkgs]//,/, }"
    else
        result "$id" PASS "none of ${P[pkgs]//,/, } is installed"
    fi
}

# pkgs_satisfied <comma list, entries may be a|b> -> sets PKS_MSG
pkgs_satisfied() {
    local list=$1 e alt got rc=0
    local -a ents alts
    PKS_MSG=""
    IFS=',' read -ra ents <<<"$list"
    for e in "${ents[@]}"; do
        got=""
        IFS='|' read -ra alts <<<"$e"
        for alt in "${alts[@]}"; do
            pkg_installed "$alt" && { got=$alt; break; }
        done
        if [[ -n $got ]]; then
            PKS_MSG+="$got ${PKG_VER[$got]} installed; "
        else
            PKS_MSG+="${e//|/ or } NOT installed; "
            rc=1
        fi
    done
    return $rc
}

# apt_pkg_status <pkg> -> APT_INST APT_CAND from local apt-cache policy data
apt_pkg_status() {
    local line cur="" want=$1
    APT_INST="" APT_CAND=""
    while IFS= read -r line; do
        if [[ $line =~ ^([^[:space:]]+):[[:space:]]*$ ]]; then
            cur=${BASH_REMATCH[1]}
        elif [[ $cur == "$want" && $line =~ ^[[:space:]]+Installed:[[:space:]]*(.*)$ ]]; then
            APT_INST=${BASH_REMATCH[1]}
        elif [[ $cur == "$want" && $line =~ ^[[:space:]]+Candidate:[[:space:]]*(.*)$ ]]; then
            APT_CAND=${BASH_REMATCH[1]}
        fi
    done <"$FACT_FILE"
}

chk_pkg_installed() {
    local id=$1 ok=1 msg
    local -a ev=()
    need dpkg || return
    pkgs_satisfied "${P[pkgs]-}" || ok=0
    msg=$PKS_MSG
    if (( ! ok )) && [[ -n ${P[alt]-} ]]; then
        if pkgs_satisfied "${P[alt]-}"; then ok=1; msg="alternative set: $PKS_MSG"; fi
    fi
    if (( ok )); then ev+=("${msg%; }"); else ev+=("!${msg%; }, expected installed"); fi
    if (( ok )) && [[ ${P[latest]-0} == 1 ]]; then
        need aptpol || return
        local e alt
        local -a ents alts
        IFS=',' read -ra ents <<<"${P[pkgs]-}"
        for e in "${ents[@]}"; do
            IFS='|' read -ra alts <<<"$e"
            for alt in "${alts[@]}"; do
                pkg_installed "$alt" || continue
                apt_pkg_status "$alt"
                if [[ -z $APT_CAND || $APT_CAND == "(none)" || $APT_CAND == "$APT_INST" ]]; then
                    ev+=("$alt: installed $APT_INST is the newest version known to the local apt cache (no network check)")
                else
                    ev+=("!$alt: installed $APT_INST, candidate $APT_CAND in the local apt cache: upgrade available")
                    ok=0
                fi
                break
            done
        done
    fi
    result "$id" "$( (( ok )) && echo PASS || echo FAIL)" "${ev[@]}"
}

# --------------------------------------------------------- apt_config ------
chk_apt_config() {
    local id=$1 key=${P[key]-} exp=${P[value]-} line v
    need aptcfg || return
    line=$(grep -Pi -- "^\s*${key}\s+" "$FACT_FILE" | tail -n1)
    if [[ -z $line ]]; then
        result "$id" FAIL "$key is not set in 'apt-config dump', expected $key \"$exp\";"
        return
    fi
    v=$(sed -E 's/^[^"]*"([^"]*)".*/\1/' <<<"$line")
    if list_has "${P[accept]:-$exp}" "${v,,}"; then
        result "$id" PASS "$line (expected $exp)"
    else
        result "$id" FAIL "$line (expected $exp)"
    fi
}

# ---------------------------------------------------------------- gdm ------
chk_gdm() {
    result "$1" MANUAL "gdm3 is installed; this GDM setting is not automated in v1" \
        "Decision required: run the gsettings commands from the benchmark audit for ${1} (${P[key]-gdm}) and confirm the setting is locked and meets policy"
}

# ------------------------------------------------------------- manual ------
chk_manual() {
    local id=$1 fn="man_ev_${1//./_}"
    local -a ev=()
    if declare -F "$fn" >/dev/null; then
        mapfile -t ev < <("$fn")
    fi
    result "$id" MANUAL "${ev[@]}" "Decision required: ${P[hint]:-review against site policy}"
}

# ---------------------------------------------------------- pam_module -----
# pam_lines <file> <module> -> PAM_LINES (uncommented lines mentioning the module)
pam_lines() {
    local f=$R/etc/pam.d/$1 line
    PAM_LINES=()
    [[ -r $f ]] || return 1
    while IFS= read -r line; do
        [[ $line =~ ^[[:space:]]*# ]] && continue
        [[ $line =~ (^|[^[:alnum:]_])${2//./\\.}([^[:alnum:]_]|$) ]] && PAM_LINES+=("$line")
    done <"$f"
    return 0
}

# pam_args_of <line> <module> -> REPLY: the arguments after the module name
pam_args_of() {
    local l=$1 m=${2//./\\.}
    if [[ $l =~ $m[[:space:]]*(.*)$ ]]; then REPLY=${BASH_REMATCH[1]}; else REPLY=""; fi
}

# arg_value <args> <key> -> REPLY ("" + rc 1 when key not given)
arg_value() {
    local a
    for a in $1; do
        if [[ $a == "$2="* ]]; then REPLY=${a#*=}; return 0; fi
    done
    REPLY=""
    return 1
}
has_arg() { local a; for a in $1; do [[ $a == "$2" ]] && return 0; done; return 1; }

chk_pam_module() {
    local id=$1 mod=${P[module]-} mode=${P[mode]-} f l
    local -a files bad=() ok=() ev=()
    IFS=',' read -ra files <<<"${P[files]-}"
    case $mode in
        present_all)
            local need_arg
            for f in "${files[@]}"; do
                if ! pam_lines "$f" "$mod"; then bad+=("/etc/pam.d/$f: cannot be read"); continue; fi
                if (( ${#PAM_LINES[@]} == 0 )); then bad+=("/etc/pam.d/$f: no active $mod line"); continue; fi
                ok+=("/etc/pam.d/$f: ${PAM_LINES[0]}")
            done
            # required arguments per file, "file:arg|file:arg"
            if [[ -n ${P[args]-} ]]; then
                local pair pf pa found
                local -a pairs
                IFS='|' read -ra pairs <<<"${P[args]-}"
                for pair in "${pairs[@]}"; do
                    pf=${pair%%:*} pa=${pair#*:}
                    [[ -z $pa ]] && continue
                    found=0
                    pam_lines "$pf" "$mod" || continue
                    for l in "${PAM_LINES[@]}"; do has_arg "$l" "$pa" && found=1; done
                    (( found )) || bad+=("/etc/pam.d/$pf: no $mod line with argument '$pa'")
                done
            fi
            ;;
        forbid_arg)
            local rx=${P[argre]-}
            for f in "${files[@]}"; do
                pam_lines "$f" "$mod" || continue
                for l in "${PAM_LINES[@]}"; do
                    pam_args_of "$l" "$mod"
                    if grep -Pq -- "(^|\s)($rx)(\s|\$)" <<<"$REPLY"; then
                        bad+=("/etc/pam.d/$f: $l")
                    else
                        ok+=("/etc/pam.d/$f: no forbidden argument ($rx) on: $l")
                    fi
                done
            done
            ;;
        require_arg)
            local rx=${P[argre]-} typ=${P[type]:-password} seen=0
            for f in "${files[@]}"; do
                pam_lines "$f" "$mod" || { bad+=("/etc/pam.d/$f: cannot be read"); continue; }
                for l in "${PAM_LINES[@]}"; do
                    [[ $l =~ ^[[:space:]]*$typ[[:space:]] ]] || continue
                    seen=1
                    pam_args_of "$l" "$mod"
                    if grep -Pq -- "(^|\s)($rx)(\s|\$)" <<<"$REPLY"; then
                        ok+=("/etc/pam.d/$f: $l")
                    else
                        bad+=("/etc/pam.d/$f: $l does not include $rx")
                    fi
                done
            done
            (( seen )) || bad+=("no active $typ line for $mod in ${P[files]-}")
            ;;
        conf_or_arg)
            pam_conf_or_arg
            return
            ;;
    esac
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# pwhistory: value or flag set in /etc/security/pwhistory.conf OR on the module
# line in common-password, but not both (5.3.3.3.x).
pam_conf_or_arg() {
    local id=$CUR_ID mod=${P[module]-} key=${P[key]-} op=${P[op]-flag} exp=${P[value]-} conf=${P[conf]-}
    local cv="" av="" l cfound=0 afound=0 f=$R$conf line
    local -a ev=()
    if [[ -r $f ]]; then
        while IFS= read -r line; do
            [[ $line =~ ^[[:space:]]*# ]] && continue
            if [[ $op == flag ]]; then
                [[ $line =~ ^[[:space:]]*$key[[:space:]]*(#.*)?$ ]] && { cfound=1; cv=set; }
            elif [[ $line =~ ^[[:space:]]*$key[[:space:]]*=[[:space:]]*([^[:space:]#]+) ]]; then
                cfound=1; cv=${BASH_REMATCH[1]}
            fi
        done <"$f"
    fi
    if pam_lines common-password "$mod"; then
        for l in "${PAM_LINES[@]}"; do
            [[ $l =~ ^[[:space:]]*password[[:space:]] ]] || continue
            pam_args_of "$l" "$mod"
            if [[ $op == flag ]]; then
                has_arg "$REPLY" "$key" && { afound=1; av=set; }
            elif arg_value "$REPLY" "$key"; then
                afound=1; av=$REPLY
            fi
        done
    fi
    (( cfound )) && ev+=("$conf: $key${cv:+ = $cv}")
    (( afound )) && ev+=("/etc/pam.d/common-password ($mod): $key${av:+=$av}")
    if (( cfound && afound )); then
        result "$id" FAIL "${ev[@]}" "$key is configured in both $conf and the PAM stack; use only one method"
        return
    fi
    if (( ! cfound && ! afound )); then
        result "$id" FAIL "$key is set neither in $conf nor on the $mod line in /etc/pam.d/common-password"
        return
    fi
    local val=$cv
    (( afound )) && val=$av
    if [[ $op == flag ]] || val_ok "$op" "$exp" "$val"; then
        result "$id" PASS "${ev[@]}" "expected ${op/#flag/option present} ${exp:+$op $exp}"
    else
        result "$id" FAIL "${ev[@]}" "expected $key $op $exp"
    fi
}

# ------------------------------------------------------------ conf_kv ------
# Effective value of key from an ordered list of plain "key = value" files.
# kv_collect <key> <files...> -> KV_VALUE KV_FILE KV_ALL KV_FOUND
kv_collect() {
    local key=$1 f line
    shift
    KV_VALUE="" KV_FILE="" KV_ALL="" KV_FOUND=0
    for f in "$@"; do
        [[ -r $R$f ]] || continue
        while IFS= read -r line; do
            [[ $line =~ ^[[:space:]]*# ]] && continue
            if [[ $line =~ ^[[:space:]]*([A-Za-z0-9_]+)[[:space:]]*=[[:space:]]*([^[:space:]#]+) ]]; then
                if [[ ${BASH_REMATCH[1],,} == "${key,,}" ]]; then
                    KV_VALUE=${BASH_REMATCH[2]} KV_FILE=$f KV_FOUND=1
                    KV_ALL+="$f: $key=$KV_VALUE; "
                fi
            elif [[ $line =~ ^[[:space:]]*([A-Za-z0-9_]+)[[:space:]]*$ && ${BASH_REMATCH[1],,} == "${key,,}" ]]; then
                KV_VALUE=set KV_FILE=$f KV_FOUND=1
                KV_ALL+="$f: $key; "
            fi
        done <"$R$f"
    done
}

# conf file list with globs, in precedence order (later wins)
conf_files() {
    local spec=$1 e
    CONF_FILES=()
    local -a ents
    IFS=',' read -ra ents <<<"$spec"
    for e in "${ents[@]}"; do
        expand_glob "$e"
        if [[ $e == *[*?[]* ]]; then
            local -a sorted
            mapfile -t sorted < <(printf '%s\n' "${GLOB[@]}" | LC_ALL=C sort)
            CONF_FILES+=("${sorted[@]}")
        else
            CONF_FILES+=("$e")
        fi
    done
}

chk_conf_kv() {
    local id=$1 key=${P[key]-} op=${P[op]-} exp=${P[value]-} absent=${P[absent]:-fail} v="" where="" bad=0
    local -a ev=()
    case ${P[src]-} in
        catcfg:*)
            if ! catcfg_get "${P[src]#catcfg:}" "${P[section]-}" "$key"; then
                result "$id" ERROR "cannot read effective configuration of ${P[src]#catcfg:}: ${NEED_ERR}"
                return
            fi
            if [[ -n ${P[altkey]-} ]]; then
                # NTP / FallbackNTP style: any of the keys set
                local k
                local -a ks
                IFS=',' read -ra ks <<<"${P[altkey]-}"
                local got=""
                for k in "${ks[@]}"; do
                    catcfg_get "${P[src]#catcfg:}" "${P[section]-}" "$k" || continue
                    if [[ -n $CC_VALUE ]]; then
                        ev+=("$k=$CC_VALUE (in $CC_FILE)")
                        got=1
                    else
                        ev+=("$k is not set")
                    fi
                done
                if [[ -n $got ]]; then
                    result "$id" PASS "${ev[@]}" "verify the configured servers against site policy"
                else
                    result "$id" FAIL "${ev[@]}" "expected at least one of ${P[altkey]//,/, } to be set to an approved time server"
                fi
                return
            fi
            v=$CC_VALUE where=$CC_FILE
            if [[ -z $v ]]; then
                if [[ $absent == default && -n $CC_DEFAULT ]]; then
                    v=$CC_DEFAULT where="built-in default, not set explicitly"
                fi
            fi
            ;;
        files:*)
            conf_files "${P[src]#files:}"
            kv_collect "$key" "${CONF_FILES[@]}"
            v=$KV_VALUE where=$KV_FILE
            [[ -n $KV_ALL ]] && ev+=("assignments (last wins): ${KV_ALL%; }")
            ;;
    esac
    if [[ -z $v ]]; then
        case $absent in
            pass) ev+=("$key is not set; the module default is compliant") ;;
            *)
                if [[ $op == flag ]]; then
                    ev+=("!$key is not set, expected it to be present")
                else
                    op_text "$op" "$exp"; ev+=("!$key is not set, expected $REPLY")
                fi
                bad=1 ;;
        esac
    else
        if [[ $op == flag ]]; then
            ev+=("$key is set (in $where)")
        elif val_ok "$op" "$exp" "$v"; then
            op_text "$op" "$exp"; ev+=("$key=$v ($where), expected $REPLY")
        else
            op_text "$op" "$exp"; ev+=("!$key=$v ($where), expected $REPLY")
            bad=1
        fi
    fi
    # arguments on the PAM module line override the configuration file
    if [[ -n ${P[pam_file]-} ]] && pam_lines "${P[pam_file]-}" "${P[pam_mod]-}"; then
        local l a pv
        for l in "${PAM_LINES[@]}"; do
            [[ $l =~ ^[[:space:]]*${P[pam_type]:-password}[[:space:]]+(requisite|required|sufficient)[[:space:]] ]] || continue
            pam_args_of "$l" "${P[pam_mod]-}"
            a=$REPLY
            if [[ $op == flag ]]; then
                has_arg "$a" "$key" && ev+=("/etc/pam.d/${P[pam_file]-}: module argument $key is also present")
            elif arg_value "$a" "$key"; then
                pv=$REPLY
                if val_ok "$op" "$exp" "$pv"; then
                    ev+=("/etc/pam.d/${P[pam_file]-}: module argument $key=$pv overrides the file and is compliant")
                else
                    op_text "$op" "$exp"; ev+=("!/etc/pam.d/${P[pam_file]-}: module argument $key=$pv overrides the file, expected $REPLY")
                    bad=1
                fi
            fi
        done
    fi
    # 6.1.1.1.3 also needs both services loaded and active
    if [[ -n ${P[units_active]-} ]]; then
        need units || return
        local u
        local -a us
        IFS=',' read -ra us <<<"${P[units_active]-}"
        for u in "${us[@]}"; do
            if unit_is_active "$u"; then ev+=("$u is active"); else ev+=("!$u is not active"); bad=1; fi
        done
    fi
    result "$id" "$( (( bad )) && echo FAIL || echo PASS)" "${ev[@]}"
}

# ==== lib/checks_custom/s1_initial_setup.sh ====
# lib/checks_custom/s1_initial_setup.sh - custom checks, benchmark section 1.
# Each function names the benchmark ID it ports and which Audit steps it implements.
# Checks read facts and files only (through $R and the fact accessors).
# shellcheck disable=SC2034,SC2154

# 1.2.1.3 Ensure access to gpg key files are configured.
# Step 1: gpg files in /usr/share/keyrings and /etc/apt/trusted.gpg.d must be 0644 or
# stricter and root:root (fact apt_keyfiles lists the offenders found by the PDF's find).
# Step 2: key files named by Signed-By outside those dirs must be 0644 or stricter, root:root.
cus_1_2_1_3() {
    local id=$1 m u g p f key
    local -a bad=() ok=() keys=() PERM_OK=() PERM_BAD=()
    _need_fact apt_keyfiles || { result "$id" ERROR "fact apt_keyfiles unavailable: $NEED_ERR"; return; }
    while IFS=$'\t' read -r m u g p; do
        mode4 "$m"
        [[ -n $p ]] && bad+=("$p: mode $M4 owner $u group $g; expected 0644 or stricter and root:root")
    done <"$FACT_FILE"
    [[ ${#bad[@]} -eq 0 ]] && ok+=("step 1: all *gpg files in /usr/share/keyrings and /etc/apt/trusted.gpg.d are 0644 or stricter, root:root")
    shopt -s nullglob
    for f in "$R/etc/apt/sources.list" "$R"/etc/apt/sources.list.d/*.list "$R"/etc/apt/sources.list.d/*.sources; do
        [[ -r $f ]] || continue
        while IFS= read -r key; do
            keys+=("$key")
        done < <(grep -Pho -- '\bSigned-By\b\s*[=:]\s*\K\S+' "$f" 2>/dev/null)
    done
    shopt -u nullglob
    if (( ${#keys[@]} )); then
        local -a uniq
        mapfile -t uniq < <(printf '%s\n' "${keys[@]}" | LC_ALL=C sort -u)
        for key in "${uniq[@]}"; do
            key=${key//\"/}
            key=${key%,}
            [[ $key == /* ]] || continue
            case $key in /usr/share/keyrings/*|/etc/apt/trusted.gpg.d/*) continue ;; esac
            perm_eval "$key" 644 root root || true
        done
        bad+=("${PERM_BAD[@]}")
        ok+=("${PERM_OK[@]}")
    fi
    (( ${#keys[@]} )) || ok+=("step 2: no Signed-By key files outside the standard keyring directories")
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# 1.2.1.10 Ensure repositories are set to https in /etc/apt/sources.list.
# The PDF greps '^\s*deb\s+http://'. This port also catches deb-src and an options
# bracket in front of the URI (deb [signed-by=...] http://...).
cus_1_2_1_10() {
    local id=$1 f=$R/etc/apt/sources.list hits
    if [[ ! -r $f ]]; then
        result "$id" PASS "/etc/apt/sources.list does not exist; nothing to check"
        return
    fi
    hits=$(grep -Pin -- '^\s*deb(-src)?\s+(\[[^]]*\]\s+)?http://' "$f")
    if [[ -n $hits ]]; then
        result "$id" FAIL "plain http repository in /etc/apt/sources.list (line: entry), expected https:" "${hits//$'\n'/$'\n'}"
    else
        result "$id" PASS "/etc/apt/sources.list: no deb/deb-src entry uses plain http://"
    fi
}

# 1.2.1.11 Ensure repositories are set to https in /etc/apt/sources.list.d directory.
# Step 1: *.list files (as 1.2.1.10). Step 2: deb822 *.sources files, URIs: field.
cus_1_2_1_11() {
    local id=$1 f line n tok
    local -a bad=() checked=()
    shopt -s nullglob
    for f in "$R"/etc/apt/sources.list.d/*.list; do
        checked+=("${f#"$R"}")
        while IFS= read -r line; do
            bad+=("${f#"$R"}:$line")
        done < <(grep -Pin -- '^\s*deb(-src)?\s+(\[[^]]*\]\s+)?http://' "$f")
    done
    for f in "$R"/etc/apt/sources.list.d/*.sources; do
        checked+=("${f#"$R"}")
        n=0
        local inuris=0
        while IFS= read -r line || [[ -n $line ]]; do
            n=$((n + 1))
            if [[ $line =~ ^[[:space:]]*# ]]; then continue; fi
            if [[ $line =~ ^[Uu][Rr][Ii][Ss]:[[:space:]]*(.*)$ ]]; then
                inuris=1
                line=${BASH_REMATCH[1]}
            elif [[ $inuris == 1 && $line =~ ^[[:space:]]+(.*)$ ]]; then
                line=${BASH_REMATCH[1]}
            else
                inuris=0
                continue
            fi
            for tok in $line; do
                [[ ${tok,,} == http://* ]] && bad+=("${f#"$R"}:$n:URIs: $tok")
            done
        done <"$f"
    done
    shopt -u nullglob
    if (( ${#bad[@]} )); then
        result "$id" FAIL "plain http repositories, expected https:" "${bad[@]}"
    elif (( ${#checked[@]} )); then
        result "$id" PASS "no plain http:// repository in: ${checked[*]}"
    else
        result "$id" PASS "no repository files in /etc/apt/sources.list.d"
    fi
}

# 1.3.1.2 Ensure AppArmor is enabled.
# Not disabled on the kernel command line (grub.cfg linux lines,
# /etc/default/grub.d/apparmor.cfg; the running /proc/cmdline is checked too),
# apparmor.service enabled and active, and at least one profile loaded.
cus_1_3_1_2() {
    local id=$1 n
    local -a bad=() ok=()
    need units || return
    if grep -Pqs -- '^\s*linux.*\bapparmor=0\b' "$R/boot/grub/grub.cfg"; then
        bad+=("/boot/grub/grub.cfg: a linux line contains apparmor=0")
    else
        ok+=("/boot/grub/grub.cfg: no linux line contains apparmor=0")
    fi
    if grep -Pqs -- 'apparmor=0' "$R/etc/default/grub.d/apparmor.cfg"; then
        bad+=("/etc/default/grub.d/apparmor.cfg: contains apparmor=0")
    fi
    if grep -Pqs -- '\bapparmor=0\b' "$R/proc/cmdline"; then
        bad+=("/proc/cmdline: the running kernel was booted with apparmor=0")
    fi
    unit_describe apparmor.service
    if unit_is_enabled apparmor.service && unit_is_active apparmor.service; then
        ok+=("apparmor.service: $REPLY (enabled/active)")
    else
        bad+=("apparmor.service: $REPLY (enabled-state/active-state), expected enabled and active")
    fi
    if _need_fact aa_status; then
        n=$(grep -Po -- '^\s*\K[0-9]+(?=\s+profiles are loaded)' "$FACT_FILE" | head -n1)
        if [[ -n $n ]] && (( n > 0 )); then
            ok+=("$n AppArmor profiles are loaded")
        else
            bad+=("no AppArmor profiles are loaded (apparmor_status reports ${n:-nothing})")
        fi
    else
        bad+=("apparmor_status is not available, cannot confirm loaded profiles")
    fi
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# 1.4.1 Ensure bootloader password is set.
# grub.cfg needs 'set superusers=' and a 'password_pbkdf2 <user> grub.pbkdf2.sha512...' line.
cus_1_4_1() {
    local id=$1 su pw
    local f=$R/boot/grub/grub.cfg
    if [[ ! -r $f ]]; then
        result "$id" FAIL "/boot/grub/grub.cfg does not exist or is not readable; expected 'set superusers' and a password_pbkdf2 entry"
        return
    fi
    su=$(grep -P -- '^\s*set superusers=' "$f" | head -n1)
    pw=$(grep -P -- '^\s*password_pbkdf2\s+\S+\s+grub\.pbkdf2\.sha512\.' "$f" | awk '{print $1" "$2" "substr($3,1,20)"..."}' | head -n1)
    local -a bad=() ok=()
    [[ -n $su ]] && ok+=("grub.cfg: $su") || bad+=("grub.cfg: no 'set superusers=\"<username>\"' line")
    [[ -n $pw ]] && ok+=("grub.cfg: $pw (hash shortened)") || bad+=("grub.cfg: no 'password_pbkdf2 <username> grub.pbkdf2.sha512...' line")
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# 1.5.7 Ensure Automatic Error Reporting is configured.
# If apport is installed, /etc/default/apport must not have enabled=<non-0>, and
# apport.service must not be active.
cus_1_5_7() {
    local id=$1 hit
    local -a bad=() ok=()
    need dpkg units || return
    if pkg_installed apport; then
        hit=$(grep -Psi -- '^\s*enabled\s*=\s*[^0]\b' "$R/etc/default/apport" 2>/dev/null)
        if [[ -n $hit ]]; then
            bad+=("/etc/default/apport: $hit, expected enabled=0")
        else
            ok+=("/etc/default/apport: enabled is not set to a non-0 value")
        fi
    else
        ok+=("apport is not installed")
    fi
    if unit_is_active apport.service; then
        bad+=("apport.service is active, expected not active")
    else
        ok+=("apport.service is not active")
    fi
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# 1.5.10 Ensure core file size is configured.
# A '* hard core' limit in limits.conf / limits.d must exist and none may be above 0.
cus_1_5_10() {
    local id=$1 f line val
    local -a files=() hits=() bad=()
    [[ -r $R/etc/security/limits.conf ]] && files+=("/etc/security/limits.conf")
    shopt -s nullglob
    local d
    mapfile -t d < <(printf '%s\n' "$R"/etc/security/limits.d/*.conf | LC_ALL=C sort)
    shopt -u nullglob
    for f in "${d[@]}"; do [[ -n $f ]] && files+=("${f#"$R"}"); done
    local last=""
    for f in "${files[@]}"; do
        while IFS= read -r line; do
            hits+=("$f: $line")
            if [[ $line =~ hard[[:space:]]+core[[:space:]]+([^[:space:]#]+) ]]; then
                val=${BASH_REMATCH[1]}
                last=$val
                if ! is_uint "$val" || (( val > 0 )); then bad+=("$f: '* hard core $val', expected 0"); fi
            fi
        done < <(grep -Psi -- '^\s*\*\s+hard\s+core\b' "$R$f")
    done
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${hits[@]}"
    elif (( ${#hits[@]} == 0 )); then
        result "$id" FAIL "no '* hard core 0' line in /etc/security/limits.conf or /etc/security/limits.d/*.conf"
    else
        result "$id" PASS "${hits[@]}" "effective value (last line wins): hard core $last"
    fi
}

# --- banners (1.6.1 - 1.6.4) ---------------------------------------------------
# banner_scan <files...>: BAN_HITS = lines with \m \r \s \v or the OS name
banner_scan() {
    local f hits
    BAN_HITS=() BAN_SEEN=()
    banner_re
    for f in "$@"; do
        [[ -r $R$f && -f $R$f ]] || continue
        BAN_SEEN+=("$f")
        hits=$(grep -Pni -- "$BANNER_RE" "$R$f" | head -n 3)
        [[ -n $hits ]] && BAN_HITS+=("$f: ${hits//$'\n'/ | }")
    done
}

# glob helper that returns unprefixed paths in GLOB (existing, sorted)
glob_files() {
    local p f
    GLOB=()
    shopt -s nullglob
    for p in "$@"; do
        for f in $R$p; do GLOB+=("${f#"$R"}"); done
    done
    shopt -u nullglob
}

# 1.6.1 Ensure /etc/motd is configured: no \m \r \s \v and no OS name in /etc/motd, /etc/motd.d/*.
cus_1_6_1() {
    local id=$1
    glob_files '/etc/motd' '/etc/motd.d/*'
    banner_scan "${GLOB[@]}"
    if (( ${#BAN_HITS[@]} )); then
        result "$id" FAIL "OS information or escape codes (\\m \\r \\s \\v, OS name) found:" "${BAN_HITS[@]}"
    elif (( ${#BAN_SEEN[@]} )); then
        result "$id" PASS "no OS information in: ${BAN_SEEN[*]}; review the text against site policy"
    else
        result "$id" PASS "no motd files exist (a message of the day is optional)"
    fi
}

# banner_site_check <file>: optional exact match against BANNER_FILE from site.conf
banner_site_check() {
    SITE_BAN_MSG="" SITE_BAN_BAD=0
    local sf=${SITE[BANNER_FILE]-}
    [[ -n $sf ]] || return 0
    if [[ ! -r $R$sf ]]; then
        SITE_BAN_MSG="BANNER_FILE $sf from site.conf is not readable"
        SITE_BAN_BAD=1
    elif [[ -r $R$1 ]] && cmp -s -- "$R$1" "$R$sf"; then
        SITE_BAN_MSG="$1 matches the site banner $sf"
    else
        SITE_BAN_MSG="$1 differs from the site banner $sf"
        SITE_BAN_BAD=1
    fi
}

# 1.6.2 Ensure /etc/issue is configured: /etc/issue and issue.d fragments carry no OS information.
cus_1_6_2() {
    local id=$1
    glob_files '/etc/issue' '/usr/lib/issue.d/*' '/etc/issue.d/*' '/run/issue.d/*'
    banner_scan "${GLOB[@]}"
    banner_site_check /etc/issue
    if (( ${#BAN_HITS[@]} )); then
        result "$id" FAIL "OS information or escape codes (\\m \\r \\s \\v, OS name) found:" "${BAN_HITS[@]}"
    elif (( SITE_BAN_BAD )); then
        result "$id" FAIL "$SITE_BAN_MSG"
    else
        result "$id" PASS "no OS information in: ${BAN_SEEN[*]:-no issue files}" ${SITE_BAN_MSG:+"$SITE_BAN_MSG"}
    fi
}

# 1.6.3 Ensure /etc/issue.net is configured: no OS information (the file may be absent).
cus_1_6_3() {
    local id=$1
    banner_scan /etc/issue.net
    banner_site_check /etc/issue.net
    if (( ${#BAN_HITS[@]} )); then
        result "$id" FAIL "OS information or escape codes (\\m \\r \\s \\v, OS name) found:" "${BAN_HITS[@]}"
    elif (( SITE_BAN_BAD )); then
        result "$id" FAIL "$SITE_BAN_MSG"
    elif (( ${#BAN_SEEN[@]} )); then
        result "$id" PASS "/etc/issue.net has no OS information; review the text against site policy" ${SITE_BAN_MSG:+"$SITE_BAN_MSG"}
    else
        result "$id" PASS "/etc/issue.net does not exist (the benchmark notes it may be absent; creating it with the site banner is recommended)"
    fi
}

# 1.6.4 Ensure pam_motd is configured: for sshd, login, su and gdm-password, a
# pam_motd.so session line with motd=<file> must not point at a file that holds
# OS information (the PDF script's test).
cus_1_6_4() {
    local id=$1 svc file line mp
    local -a bad=() ok=()
    banner_re
    for svc in sshd login su gdm-password; do
        if [[ -f $R/etc/pam.d/$svc ]]; then file=/etc/pam.d/$svc
        elif [[ -f $R/usr/lib/pam.d/$svc ]]; then file=/usr/lib/pam.d/$svc
        else continue; fi
        while IFS= read -r line; do
            while IFS= read -r mp; do
                mp=${mp#\"}; mp=${mp%\"}; mp=${mp#\'}; mp=${mp%\'}
                [[ -r $R$mp ]] || continue
                if grep -Pqi -- "$BANNER_RE" "$R$mp"; then
                    bad+=("$file: $line -> $mp contains OS information or escape codes")
                else
                    ok+=("$file: motd=$mp has no OS information")
                fi
            done < <(grep -oP '\bmotd=\K"[^"]+"|\bmotd=\K'\''[^'\'']+'\''|\bmotd=\K\S+' <<<"$line")
        done < <(grep -Pi -- '^\s*session\s+(required|optional)\s+pam_motd\.so\b.*\bmotd=' "$R$file" 2>/dev/null)
    done
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]:-no pam_motd.so line with an explicit motd= argument found in sshd, login, su or gdm-password}"
    fi
}

# --- manual evidence ----------------------------------------------------------
man_ev_1_1_1_11() {
    if need_mounts && need_lsmod && need_modprobe && need_kmod; then
        local m="" t
        for t in "${MNT_TARGETS[@]}"; do m+="${MNT_FSTYPE[$t]} "; done
        printf 'filesystem types currently mounted: %s\n' "$(tr ' ' '\n' <<<"$m" | LC_ALL=C sort -u | tr '\n' ' ')"
        local mod n cnt=0 unprotected=""
        while IFS= read -r mod; do
            n=$(basename -- "$mod"); n=${n%%.*}; n=${n//-/_}
            [[ ${LSMOD[$n]+x} ]] && printf 'loaded filesystem module: %s\n' "$n"
            if [[ -z ${MOD_BLACKLIST[$n]+x} || -z ${MOD_INSTALL[$n]+x} ]]; then
                cnt=$((cnt + 1))
                (( cnt <= 15 )) && unprotected+="$n "
            fi
        done < <(grep -- '/kernel/fs/' "$FACTS_DIR/kmod_files" | grep -v '/kernel/fs/nls/' | LC_ALL=C sort -u)
        printf 'filesystem modules without both blacklist and install override: %s%s\n' "$cnt" "${unprotected:+ (first: ${unprotected% })}"
    else
        printf 'could not collect module facts\n'
    fi
}

man_ev_1_2_1_1() {
    local f hits
    shopt -s nullglob
    for f in "$R/etc/apt/sources.list" "$R"/etc/apt/sources.list.d/*.list; do
        [[ -r $f ]] || continue
        hits=$(grep -Pn -- '^\s*(deb(-src)?)\s+(\[(?![^\]]*\bSigned-By\b)[^\]]*\]|[^\[])' "$f" | head -n 5)
        [[ -n $hits ]] && printf '%s: entry without Signed-By: %s\n' "${f#"$R"}" "${hits//$'\n'/ | }"
    done
    for f in "$R"/etc/apt/sources.list.d/*.sources; do
        awk -v F="${f#"$R"}" 'function flush(){ if (u && !s) print F ": stanza ending near line " ln " has URIs but no Signed-By"; u=0; s=0 }
            /^[[:blank:]]*$/ { flush() } /^[[:blank:]]*URIs:[[:blank:]]*[^[:blank:]]/ { u=1 }
            /^[[:blank:]]*Signed-By:[[:blank:]]*[^[:blank:]]/ { s=1 } { ln=NR } END { flush() }' "$f"
    done
    shopt -u nullglob
}

man_ev_1_2_2_1() {
    [[ -e $R/var/run/reboot-required || -e $R/run/reboot-required ]] && printf 'a reboot is required (reboot-required exists)\n'
    printf 'pending updates are not checked: that needs apt update (network)\n'
}

# ==== lib/checks_custom/s2_services.sh ====
# lib/checks_custom/s2_services.sh - custom checks, benchmark section 2.
# shellcheck disable=SC2034,SC2154

# mta_loopback_only <setting text>: every address token must be a loopback address.
mta_loopback_only() {
    local t v=${1#*=} 
    v=${v//[<;,]/ }
    [[ -n ${v//[[:space:]]/} ]] || return 0
    for t in $v; do
        t=${t#[}; t=${t%]}
        case ${t,,} in
            loopback-only|localhost|127.*|::1) ;;
            *) return 1 ;;
        esac
    done
    return 0
}

# 2.1.22 Ensure mail transfer agents are configured for local-only mode.
# Ports 25, 465 and 587 must not listen on a non-loopback address, and the MTA's own
# interface setting must not bind all interfaces. Deviation from the PDF script: its
# regex accepts 0.0.0.0 and rejects 127.0.0.1; this port accepts loopback values only.
cus_2_1_22() {
    local id=$1 port line local_addr cfg
    local -a f
    local -a bad=() ok=()
    need ss || return
    for port in 25 465 587; do
        local nonloop=0 any=0
        while IFS= read -r line; do
            # Netid State Recv-Q Send-Q Local:Port Peer:Port Process
            read -ra f <<<"$line"
            local_addr=${f[4]-}
            [[ $local_addr == *:"$port" ]] || continue
            any=1
            case ${local_addr%:*} in
                127.0.0.1|'[::1]'|::1) ;;
                *) nonloop=1; bad+=("port $port listens on $local_addr (non-loopback)") ;;
            esac
        done <"$FACT_FILE"
        (( any && ! nonloop )) && ok+=("port $port listens on loopback only")
        (( any )) || ok+=("nothing listens on port $port")
    done
    if fact mta_cfg && [[ -s $FACT_FILE ]]; then
        cfg=$(head -n1 "$FACT_FILE")
        if mta_loopback_only "${cfg#*: }"; then
            ok+=("MTA interface setting is loopback only: $cfg")
        else
            bad+=("MTA is bound to a non-loopback interface setting: $cfg")
        fi
    else
        ok+=("no MTA configuration found (MTA not detected or not in use)")
    fi
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

man_ev_2_1_23() {
    if need_ss; then
        printf 'listening sockets (ss -plntu): %s\n' "$(wc -l <"$FACT_FILE" | tr -d ' ')"
        local line
        local -a f
        while IFS= read -r line; do
            read -ra f <<<"$line"
            printf '%s %s %s\n' "${f[0]-}" "${f[4]-}" "${f[*]:6}"
        done <"$FACT_FILE"
        if [[ -n ${SITE[APPROVED_LISTENERS]-} ]]; then
            local e proto port found
            local -a ents
            IFS=',' read -ra ents <<<"${SITE[APPROVED_LISTENERS]}"
            while IFS= read -r line; do
                read -ra f <<<"$line"
                proto=${f[0]-} port=${f[4]##*:}
                found=0
                for e in "${ents[@]}"; do [[ $e == "$proto:$port" ]] && found=1; done
                (( found )) || printf 'NOT in APPROVED_LISTENERS: %s %s\n' "$proto" "${f[4]-}"
            done <"$FACT_FILE"
        else
            printf 'APPROVED_LISTENERS is not set in site.conf; compare the list with site policy by hand\n'
        fi
    else
        printf 'ss output unavailable\n'
    fi
}

# 2.3.1.1 Ensure a single time synchronization daemon is in use.
# "In use" means enabled or active, as in the PDF script. Exactly one of
# systemd-timesyncd.service and chrony.service must be in use.
cus_2_3_1_1() {
    local id=$1 d u s
    local -a use=() info=()
    need units || return
    for u in systemd-timesyncd.service chrony.service; do
        unit_describe "$u"
        if unit_is_enabled "$u" || unit_is_active "$u"; then
            use+=("$u")
            info+=("$u is in use ($REPLY enabled-state/active-state)")
        else
            info+=("$u is not enabled and not active ($REPLY)")
        fi
    done
    case ${#use[@]} in
        1) result "$id" PASS "only one time sync daemon is in use: ${use[0]}" "${info[@]}" ;;
        0) result "$id" FAIL "no time sync daemon is in use, expected exactly one of chrony or systemd-timesyncd" "${info[@]}" ;;
        *) result "$id" FAIL "more than one time sync daemon is in use, expected exactly one" "${info[@]}" ;;
    esac
}

# 2.3.3.1 Ensure chrony is configured: a server or pool line must exist in
# /etc/chrony/chrony.conf or in files below its confdir/sourcedir directories.
cus_2_3_3_1() {
    local id=$1 conf=/etc/chrony/chrony.conf f d line path
    local -a files=("$conf") hits=() dirs=()
    if [[ ! -r $R$conf ]]; then
        result "$id" FAIL "$conf does not exist or is not readable"
        return
    fi
    while read -r _ path; do
        [[ -n $path ]] && dirs+=("$path")
    done < <(grep -Pi -- '^\s*(confdir|sourcedir)\s+\S+' "$R$conf" | awk '{print $1, $2}')
    shopt -s nullglob
    for d in "${dirs[@]}"; do
        if [[ -d $R$d ]]; then
            for f in "$R$d"/*; do [[ -f $f ]] && files+=("${f#"$R"}"); done
        else
            for f in $R$d; do [[ -f $f ]] && files+=("${f#"$R"}"); done
        fi
    done
    shopt -u nullglob
    for f in "${files[@]}"; do
        while IFS= read -r line; do
            hits+=("$f: $line")
        done < <(grep -Pi -- '^\s*(server|pool)(\s+|\s*:\s*).+\b' "$R$f" 2>/dev/null)
    done
    if (( ${#hits[@]} )); then
        result "$id" PASS "time source configured:" "${hits[@]}" "verify the servers against site policy"
    else
        result "$id" FAIL "no 'server' or 'pool' line in ${files[*]}, expected an authorized time server"
    fi
}

# 2.3.3.2 Ensure chrony is running as user _chrony: no chronyd process may run as another user.
cus_2_3_3_2() {
    local id=$1 user args cmd
    local -a bad=() seen=()
    _need_fact ps_chronyd || { result "$id" ERROR "process list unavailable: $NEED_ERR"; return; }
    while read -r user args; do
        cmd=${args%% *}
        [[ ${cmd##*/} == chronyd ]] || continue
        if [[ $user == _chrony ]]; then
            seen+=("chronyd runs as $user")
        else
            bad+=("chronyd process runs as $user, expected _chrony: $args")
        fi
    done <"$FACT_FILE"
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${seen[@]}"
    elif (( ${#seen[@]} )); then
        result "$id" PASS "${seen[@]}"
    else
        result "$id" PASS "no chronyd process is running, so none runs as another user"
    fi
}

# 2.4.1.9 Ensure access to crontab is configured (cron.allow must exist, cron.deny
# need not; both 0640 or stricter, root:root or root:crontab).
cus_2_4_1_9() {
    local id=$1
    local -a bad=() ok=() PERM_OK=() PERM_BAD=()
    if ! perm_eval /etc/cron.allow 640 root "root|crontab"; then
        bad+=("/etc/cron.allow does not exist, expected it with mode 0640 or stricter, root:root or root:crontab")
    fi
    bad+=("${PERM_BAD[@]}")
    ok+=("${PERM_OK[@]}")
    PERM_OK=() PERM_BAD=()
    if perm_eval /etc/cron.deny 640 root "root|crontab"; then
        bad+=("${PERM_BAD[@]}")
        ok+=("${PERM_OK[@]}")
    else
        ok+=("/etc/cron.deny does not exist")
    fi
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# 2.4.2.1 Ensure access to at is configured (at.allow must exist, at.deny need not;
# both 0640 or stricter, root:daemon or root:root).
cus_2_4_2_1() {
    local id=$1
    local -a bad=() ok=() PERM_OK=() PERM_BAD=()
    if ! perm_eval /etc/at.allow 640 root "daemon|root"; then
        bad+=("/etc/at.allow does not exist, expected it with mode 0640 or stricter, root:daemon or root:root")
    fi
    bad+=("${PERM_BAD[@]}")
    ok+=("${PERM_OK[@]}")
    PERM_OK=() PERM_BAD=()
    if perm_eval /etc/at.deny 640 root "daemon|root"; then
        bad+=("${PERM_BAD[@]}")
        ok+=("${PERM_OK[@]}")
    else
        ok+=("/etc/at.deny does not exist")
    fi
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# ==== lib/checks_custom/s3_network.sh ====
# lib/checks_custom/s3_network.sh - custom checks, benchmark section 3.
# shellcheck disable=SC2034,SC2154

# 3.1.2 Ensure wireless interfaces are not available.
# No wireless interface, or for every driver module of a wireless interface:
# not loadable (install ... /bin/true|false), not loaded, and deny listed.
cus_3_1_2() {
    local id=$1 m n
    local -a mods bad=() ok=()
    need modprobe lsmod || return
    _need_fact wireless_modules || { result "$id" ERROR "wireless interface list unavailable: $NEED_ERR"; return; }
    mapfile -t mods <"$FACT_FILE"
    if (( ${#mods[@]} == 0 )); then
        result "$id" PASS "the system has no wireless interfaces"
        return
    fi
    for m in "${mods[@]}"; do
        [[ -n $m ]] || continue
        n=${m//-/_}
        case ${MOD_INSTALL[$n]-} in
            /bin/true|/bin/false) ok+=("module $m is not loadable (install $n ${MOD_INSTALL[$n]})") ;;
            *) bad+=("module $m is loadable, expected 'install $n /bin/false' or /bin/true") ;;
        esac
        if [[ -n ${LSMOD[$n]+x} ]]; then bad+=("module $m is loaded"); else ok+=("module $m is not loaded"); fi
        if [[ -n ${MOD_BLACKLIST[$n]+x} ]]; then ok+=("module $m is deny listed"); else bad+=("module $m is not deny listed"); fi
    done
    if (( ${#bad[@]} )); then
        result "$id" FAIL "wireless interfaces use these driver modules: ${mods[*]}" "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "wireless driver modules ${mods[*]} are not loadable, not loaded and deny listed" "${ok[@]}"
    fi
}

man_ev_3_1_1() {
    if flag_get IPV6_ENABLED; then
        [[ $REPLY == 1 ]] && printf 'IPv6 is enabled\n' || printf 'IPv6 is not enabled\n'
    else
        printf 'IPv6 state could not be derived\n'
    fi
}

man_ev_3_2_7() {
    if need_kmod; then
        printf 'network modules available to the running kernel: %s\n' \
            "$(grep -c '/kernel/net/' "$FACTS_DIR/kmod_files")"
    fi
}

# ==== lib/checks_custom/s4_firewall.sh ====
# lib/checks_custom/s4_firewall.sh - custom checks, benchmark section 4 (ufw).
# shellcheck disable=SC2034,SC2154

# 4.1.2 Ensure ufw service is configured: ufw.service enabled and active, and
# `ufw status` reports "Status: active".
cus_4_1_2() {
    local id=$1 status
    local -a bad=() ok=()
    need units || return
    unit_describe ufw.service
    if unit_is_enabled ufw.service && unit_is_active ufw.service; then
        ok+=("ufw.service: $REPLY (enabled/active)")
    else
        bad+=("ufw.service: $REPLY (enabled-state/active-state), expected enabled and active")
    fi
    if fact ufw_status; then
        status=$(grep -Pm1 -- '^Status:' "$FACT_FILE")
        if [[ $status == "Status: active" ]]; then ok+=("ufw status: $status"); else bad+=("ufw status: ${status:-no status line}, expected 'Status: active'"); fi
    else
        bad+=("ufw status could not be read (ufw not installed?)")
    fi
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# ufw_default <direction> -> REPLY: policy word from "Default: deny (incoming), ..."
ufw_default() {
    REPLY=$(grep -Pm1 -- '^Default:' "$FACT_FILE" | grep -Po "[a-z]+(?= \($1\))" | head -n1)
}

# 4.1.3 Ensure ufw incoming default is configured: deny or reject.
cus_4_1_3() {
    local id=$1 pol
    if ! fact ufw_status; then
        result "$id" FAIL "ufw status verbose could not be read (ufw not installed?), expected 'Default: deny (incoming)'"
        return
    fi
    ufw_default incoming
    pol=$REPLY
    if [[ -z $pol ]]; then
        result "$id" FAIL "ufw reports no default policies (ufw is probably inactive), expected 'Default: deny (incoming)'" \
            "ufw status: $(grep -m1 '^Status:' "$FACT_FILE")"
    elif [[ $pol == deny || $pol == reject ]]; then
        result "$id" PASS "ufw default policy for incoming: $pol, expected deny or reject"
    else
        result "$id" FAIL "ufw default policy for incoming: $pol, expected deny or reject"
    fi
}

# 4.1.5 Ensure ufw routed default is configured: deny. When forwarding is off in the
# kernel, ufw prints "disabled (routed)"; then DEFAULT_FORWARD_POLICY in
# /etc/default/ufw is read, as the PDF's note says.
cus_4_1_5() {
    local id=$1 pol cfg
    if ! fact ufw_status; then
        result "$id" FAIL "ufw status verbose could not be read (ufw not installed?), expected 'deny (routed)'"
        return
    fi
    ufw_default routed
    pol=$REPLY
    case $pol in
        deny)
            result "$id" PASS "ufw default policy for routed: deny" ;;
        disabled)
            cfg=$(grep -Pi -- '^\s*DEFAULT_FORWARD_POLICY\s*=' "$R/etc/default/ufw" 2>/dev/null | tail -n1)
            if [[ ${cfg,,} =~ =[[:space:]]*\"?drop\"? ]]; then
                result "$id" PASS "ufw shows 'disabled (routed)' because kernel forwarding is off" "/etc/default/ufw: $cfg (DROP means deny)"
            else
                result "$id" FAIL "ufw shows 'disabled (routed)' because kernel forwarding is off" "/etc/default/ufw: ${cfg:-DEFAULT_FORWARD_POLICY not found}, expected DROP"
            fi ;;
        '')
            result "$id" FAIL "ufw reports no default policies (ufw is probably inactive), expected 'deny (routed)'" ;;
        *)
            result "$id" FAIL "ufw default policy for routed: $pol, expected deny" ;;
    esac
}

# ==== lib/checks_custom/s5_access.sh ====
# lib/checks_custom/s5_access.sh - custom checks, benchmark section 5
# (sudo, su, account policy, root and system accounts, shell environment).
# shellcheck disable=SC2034,SC2154

# ---- shared helpers (also used by section 7) -------------------------------
# cap_lines <max> <lines...>: sets CAPPED to the first <max> lines plus a count
cap_lines() {
    local max=$1
    shift
    CAPPED=("${@:1:max}")
    (( $# > max )) && CAPPED+=("... and $(($# - max)) more")
    return 0
}

ACCT_LOADED=0
declare -A VALID_SHELL=()
acct_load() {
    (( ACCT_LOADED )) && return 0
    PASSWD_L=() SHADOW_L=() GROUP_L=() ACCT_SHADOW_OK=0
    [[ -r $R/etc/passwd ]] || { NEED_ERR="/etc/passwd is not readable"; return 1; }
    [[ -r $R/etc/group ]] || { NEED_ERR="/etc/group is not readable"; return 1; }
    mapfile -t PASSWD_L <"$R/etc/passwd"
    mapfile -t GROUP_L <"$R/etc/group"
    if [[ -r $R/etc/shadow ]]; then
        mapfile -t SHADOW_L <"$R/etc/shadow"
        ACCT_SHADOW_OK=1
    fi
    VALID_SHELL=()
    local s
    if [[ -r $R/etc/shells ]]; then
        while IFS= read -r s; do
            [[ $s == /* && ${s##*/} != nologin ]] && VALID_SHELL[$s]=1
        done <"$R/etc/shells"
    fi
    ACCT_LOADED=1
}
need_acct() { acct_load; }
need_shadow() { acct_load || return 1; (( ACCT_SHADOW_OK )) || { NEED_ERR="/etc/shadow is not readable"; return 1; }; }

# login_defs_get <KEY> -> REPLY (last uncommented value), rc 1 when absent
login_defs_get() {
    local v
    v=$(grep -Pio -- "^\s*$1\s+\K\S+" "$R/etc/login.defs" 2>/dev/null | tail -n1)
    REPLY=$v
    [[ -n $v ]]
}

# ---- sudoers ----------------------------------------------------------------
SUDO_EFF=() SUDO_ALL=()
# sudoers_collect: SUDO_EFF = files sudo reads (follows include/includedir);
# SUDO_ALL = those plus every file in /etc/sudoers.d (the PDF greps the directory).
sudoers_collect() {
    SUDO_EFF=() SUDO_ALL=()
    local -A seen=()
    sudoers_walk /etc/sudoers 0
    local f
    SUDO_ALL=("${SUDO_EFF[@]}")
    shopt -s nullglob
    for f in "$R"/etc/sudoers.d/*; do
        f=${f#"$R"}
        [[ -f $R$f ]] || continue
        [[ -n ${seen[$f]+x} ]] || SUDO_ALL+=("$f")
    done
    shopt -u nullglob
}
sudoers_walk() { # sudoers_walk <file> <depth>
    local f=$1 depth=$2 line inc d g
    [[ -r $R$f && -f $R$f ]] || return 0
    for g in "${SUDO_EFF[@]}"; do [[ $g == "$f" ]] && return 0; done
    SUDO_EFF+=("$f")
    (( depth >= 10 )) && return 0
    while IFS= read -r line; do
        if [[ $line =~ ^[[:space:]]*[#@]include[[:space:]]+\"?([^[:space:]\"]+) ]]; then
            inc=${BASH_REMATCH[1]}
            [[ $inc == /* ]] || inc=/etc/$inc
            sudoers_walk "$inc" $((depth + 1))
        elif [[ $line =~ ^[[:space:]]*[#@]includedir[[:space:]]+\"?([^[:space:]\"]+) ]]; then
            d=${BASH_REMATCH[1]}
            [[ $d == /* ]] || d=/etc/$d
            shopt -s nullglob
            local ff
            for ff in "$R$d"/*; do
                ff=${ff#"$R"}
                [[ ${ff##*/} == *.* || ${ff##*/} == *~ ]] && continue
                sudoers_walk "$ff" $((depth + 1))
            done
            shopt -u nullglob
        fi
    done <"$R$f"
}
# sudo_grep <perl-regex> <files...>: prints "file: line" for each match
sudo_grep() {
    local rx=$1 f line
    shift
    for f in "$@"; do
        while IFS= read -r line; do
            printf '%s: %s\n' "$f" "$line"
        done < <(grep -Pi -- "$rx" "$R$f" 2>/dev/null)
    done
}

# 5.2.2 Ensure sudo commands use pty: no '!use_pty' anywhere in sudoers or sudoers.d,
# and an explicit 'Defaults use_pty' in a file sudo reads. sudo-rs enables use_pty by
# default, but the benchmark still requires the explicit setting.
cus_5_2_2() {
    local id=$1
    local -a neg pos
    sudoers_collect
    mapfile -t neg < <(sudo_grep '^\s*Defaults\s+([^#\n\r]+,\s*)?!use_pty\b' "${SUDO_ALL[@]}")
    mapfile -t pos < <(sudo_grep '^\s*Defaults\s+([^#\n\r]+,\s*)?use_pty\b' "${SUDO_EFF[@]}")
    if (( ${#neg[@]} )); then
        result "$id" FAIL "use_pty is disabled with !use_pty:" "${neg[@]}"
    elif (( ${#pos[@]} == 0 )); then
        result "$id" FAIL "no explicit 'Defaults use_pty' in ${SUDO_EFF[*]:-/etc/sudoers}, expected at least one (also required on sudo-rs)"
    else
        result "$id" PASS "use_pty is set explicitly:" "${pos[@]}"
    fi
}

# 5.2.3 Ensure sudo log file exists.
# Pass: Method A (sudo events reach syslog/journald) on any system, or Method B
# (Defaults logfile=) on classic sudo. This audit never runs sudo to create a test
# event, so Method A looks for existing sudo / sudo-rs entries in the journal and in
# /var/log/auth.log.
cus_5_2_3() {
    local id=$1 impl a b
    local -a logf=() ev=()
    need dpkg || return
    if pkg_installed sudo-rs; then impl=sudo-rs
    elif pkg_installed sudo; then impl="classic sudo"
    else
        result "$id" FAIL "neither sudo-rs nor sudo is installed"
        return
    fi
    ev+=("implementation: $impl")
    sudoers_collect
    if [[ $impl == "classic sudo" ]]; then
        mapfile -t logf < <(sudo_grep '^\s*Defaults\s+([^#]+,\s*)?logfile\s*=\s*("|'\'')?\S+("|'\'')?(,\s*\S+\s*)*\s*(#.*)?$' "${SUDO_ALL[@]}")
        if (( ${#logf[@]} )); then
            result "$id" PASS "Method B: logfile is set:" "${logf[@]}" "${ev[@]}"
            return
        fi
        ev+=("Method B: no 'Defaults logfile=' line in sudoers")
    else
        ev+=("Method B does not apply: sudo-rs ignores or rejects the logfile option")
    fi
    a=0
    if fact sudo_log && grep -Pq -- '\b(sudo|sudo-rs)\[[0-9]+\]|\bsudo(-rs)?:' "$FACT_FILE"; then
        a=1
        ev+=("Method A: sudo events found in the journal ($(grep -c . "$FACT_FILE") recent lines)")
    fi
    if grep -Pqs -- '\b(sudo|sudo-rs)\[[0-9]+\]:' "$R/var/log/auth.log"; then
        a=1
        ev+=("Method A: sudo events found in /var/log/auth.log")
    fi
    if (( a )); then
        result "$id" PASS "${ev[@]}" "the audit does not generate a test event; existing entries were used"
    else
        result "$id" FAIL "no evidence that sudo events are logged: no journal or auth.log entries from sudo / sudo-rs and no logfile setting" \
            "${ev[@]}" "if sudo has not been used yet, run 'sudo true' once and audit again"
    fi
}

# 5.2.5 Ensure re-authentication for privilege escalation is not disabled globally:
# no uncommented '!authenticate' in sudoers or sudoers.d.
cus_5_2_5() {
    local id=$1
    local -a hits
    sudoers_collect
    mapfile -t hits < <(sudo_grep '^\s*[^#\s].*!authenticate\b' "${SUDO_ALL[@]}")
    if (( ${#hits[@]} )); then
        result "$id" FAIL "re-authentication is disabled with !authenticate:" "${hits[@]}"
    else
        result "$id" PASS "no uncommented '!authenticate' in ${SUDO_ALL[*]}"
    fi
}

# 5.2.6 Ensure sudo timestamp_timeout is configured: explicitly set, never negative
# and never above 15 minutes.
cus_5_2_6() {
    local id=$1 line v f
    local -a bad=() ok=() hits
    sudoers_collect
    for f in "${SUDO_ALL[@]}"; do
        while IFS= read -r line; do
            v=$(grep -Po -- 'timestamp_timeout\s*=\s*\K-?[0-9]+' <<<"$line" | head -n1)
            if [[ -z $v ]]; then continue; fi
            if (( v < 0 )); then
                bad+=("$f: timestamp_timeout=$v is negative (disables the timeout)")
            elif (( v > 15 )); then
                bad+=("$f: timestamp_timeout=$v exceeds 15 minutes")
            else
                ok+=("$f: timestamp_timeout=$v")
            fi
        done < <(grep -Psi -- '^\s*Defaults\s+([^#\n\r]+,\s*)?timestamp_timeout\s*=\s*[-0-9]+' "$R$f" 2>/dev/null)
    done
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    elif (( ${#ok[@]} == 0 )); then
        result "$id" FAIL "timestamp_timeout is not explicitly configured in sudoers, expected a value from 0 to 15"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# 5.2.7 Ensure access to the su command is restricted: /etc/pam.d/su has
# 'auth required|requisite pam_wheel.so' with use_uid and group=<name>, and the
# named group has no members.
cus_5_2_7() {
    local id=$1 line grp members gl
    line=$(grep -Pi -- '^\s*auth\s+(?:required|requisite)\s+pam_wheel\.so(?=.*\buse_uid\b)(?=.*\bgroup=\S+).*' "$R/etc/pam.d/su" 2>/dev/null | head -n1)
    if [[ -z $line ]]; then
        result "$id" FAIL "/etc/pam.d/su has no 'auth required pam_wheel.so use_uid group=<name>' line (required or requisite, with use_uid and group=)"
        return
    fi
    grp=$(grep -Po -- '\bgroup=\K\S+' <<<"$line" | head -n1)
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    gl=""
    local g
    for g in "${GROUP_L[@]}"; do
        [[ $g == "$grp":* ]] && { gl=$g; break; }
    done
    if [[ -z $gl ]]; then
        result "$id" FAIL "pam_wheel names group '$grp', which does not exist in /etc/group" "/etc/pam.d/su: $line"
        return
    fi
    members=${gl##*:}
    if [[ -n $members ]]; then
        result "$id" FAIL "group $grp has members ($members), expected an empty member list" "/etc/pam.d/su: $line"
    else
        result "$id" PASS "/etc/pam.d/su: $line" "group $grp exists and has no members"
    fi
}

# ---- 5.4.1 password policy --------------------------------------------------
# shadow_hash_users: prints "name:f3:f4:f5:f6:f7" for accounts whose password field
# is a hash ($...$), the PDF's ($2~/^\$.+\$/) test.
shadow_hash_rows() {
    local l name pw f3 f4 f5 f6 f7
    for l in "${SHADOW_L[@]}"; do
        IFS=: read -r name pw f3 f4 f5 f6 f7 _ <<<"$l"
        [[ $pw =~ ^\$.+\$ ]] || continue
        printf '%s:%s:%s:%s:%s:%s\n' "$name" "$f3" "$f4" "$f5" "$f6" "$f7"
    done
}

# 5.4.1.1 Ensure password expiration is configured: PASS_MAX_DAYS 1..365 in
# /etc/login.defs and for every account with a password hash.
cus_5_4_1_1() {
    local id=$1 max v name f3 f4 f5
    local -a bad=() ok=()
    need shadow || return
    site_val PASS_MAX_DAYS 365; max=$REPLY
    if login_defs_get PASS_MAX_DAYS && is_uint "$REPLY" && (( REPLY >= 1 && REPLY <= max )); then
        ok+=("/etc/login.defs: PASS_MAX_DAYS $REPLY (expected 1 to $max)")
    else
        bad+=("/etc/login.defs: PASS_MAX_DAYS ${REPLY:-not set}, expected 1 to $max")
    fi
    while IFS=: read -r name f3 f4 f5 _; do
        if ! is_uint "$f5" || (( f5 < 1 || f5 > max )); then
            bad+=("user $name: PASS_MAX_DAYS '${f5:-empty}' in /etc/shadow, expected 1 to $max")
        fi
    done < <(shadow_hash_rows)
    (( ${#bad[@]} )) || ok+=("every account with a password has a maximum password age of 1 to $max days")
    cap_lines 25 "${bad[@]}"
    if (( ${#bad[@]} )); then result "$id" FAIL "${CAPPED[@]}" "${ok[@]}"; else result "$id" PASS "${ok[@]}"; fi
}

# 5.4.1.3 Ensure password expiration warning days is configured: PASS_WARN_AGE >= 7.
cus_5_4_1_3() {
    local id=$1 min name f3 f4 f5 f6
    local -a bad=() ok=()
    need shadow || return
    site_val PASS_WARN_AGE 7; min=$REPLY
    if login_defs_get PASS_WARN_AGE && is_uint "$REPLY" && (( REPLY >= min )); then
        ok+=("/etc/login.defs: PASS_WARN_AGE $REPLY (expected $min or more)")
    else
        bad+=("/etc/login.defs: PASS_WARN_AGE ${REPLY:-not set}, expected $min or more")
    fi
    while IFS=: read -r name f3 f4 f5 f6 _; do
        if ! is_uint "$f6" || (( f6 < min )); then
            bad+=("user $name: PASS_WARN_AGE '${f6:-empty}' in /etc/shadow, expected $min or more")
        fi
    done < <(shadow_hash_rows)
    (( ${#bad[@]} )) || ok+=("every account with a password has a warning period of $min days or more")
    cap_lines 25 "${bad[@]}"
    if (( ${#bad[@]} )); then result "$id" FAIL "${CAPPED[@]}" "${ok[@]}"; else result "$id" PASS "${ok[@]}"; fi
}

# 5.4.1.4 Ensure strong password hashing algorithm is configured: ENCRYPT_METHOD SHA512 or YESCRYPT.
cus_5_4_1_4() {
    local id=$1 line
    line=$(grep -Pi -- '^\s*ENCRYPT_METHOD\s+\S+' "$R/etc/login.defs" 2>/dev/null | tail -n1)
    if [[ ${line^^} =~ ^[[:space:]]*ENCRYPT_METHOD[[:space:]]+(SHA512|YESCRYPT)([[:space:]]|$) ]]; then
        result "$id" PASS "/etc/login.defs: $line, expected SHA512 or YESCRYPT"
    else
        result "$id" FAIL "/etc/login.defs: ${line:-ENCRYPT_METHOD not set}, expected SHA512 or YESCRYPT"
    fi
}

# 5.4.1.5 Ensure inactive password lock is configured: INACTIVE 0..45 in the useradd
# defaults (what `useradd -D` prints) and in every account with a password hash.
cus_5_4_1_5() {
    local id=$1 max v name f3 f4 f5 f6 f7
    local -a bad=() ok=()
    need shadow || return
    site_val INACTIVE 45; max=$REPLY
    v=$(grep -Pio -- '^\s*INACTIVE\s*=\s*\K-?[0-9]+' "$R/etc/default/useradd" 2>/dev/null | tail -n1)
    if is_int "$v" && (( v >= 0 && v <= max )); then
        ok+=("/etc/default/useradd: INACTIVE=$v (expected 0 to $max)")
    else
        bad+=("/etc/default/useradd: INACTIVE=${v:-not set}, expected 0 to $max")
    fi
    while IFS=: read -r name f3 f4 f5 f6 f7; do
        if ! is_int "$f7" || (( f7 < 0 || f7 > max )); then
            bad+=("user $name: INACTIVE '${f7:-empty}' days in /etc/shadow, expected 0 to $max")
        fi
    done < <(shadow_hash_rows)
    (( ${#bad[@]} )) || ok+=("every account with a password locks after $max inactive days or fewer")
    cap_lines 25 "${bad[@]}"
    if (( ${#bad[@]} )); then result "$id" FAIL "${CAPPED[@]}" "${ok[@]}"; else result "$id" PASS "${ok[@]}"; fi
}

# 5.4.1.6 Ensure all users last password change date is in the past.
cus_5_4_1_6() {
    local id=$1 today name f3 f4
    local -a bad=()
    need shadow || return
    today=$((EPOCHSECONDS / 86400))
    while IFS=: read -r name f3 f4 _; do
        is_uint "$f3" || continue
        (( f3 > today )) && bad+=("user $name: last password change is day $f3 since 1970, which is in the future (today is day $today)")
    done < <(shadow_hash_rows)
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}"
    else
        result "$id" PASS "no account with a password has a last-change date in the future"
    fi
}

# ---- 5.4.2 root and system accounts -----------------------------------------
# 5.4.2.1 Ensure root is the only UID 0 account.
cus_5_4_2_1() {
    local id=$1 l name uid
    local -a hits=()
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r name _ uid _ <<<"$l"
        [[ $uid == 0 ]] && hits+=("$name")
    done
    if [[ ${#hits[@]} -eq 1 && ${hits[0]} == root ]]; then
        result "$id" PASS "only root has UID 0"
    else
        result "$id" FAIL "accounts with UID 0: ${hits[*]:-none}, expected only root"
    fi
}

# 5.4.2.2 Ensure root is the only GID 0 account (sync, shutdown, halt, operator excluded).
cus_5_4_2_2() {
    local id=$1 l name gid
    local -a hits=()
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r name _ _ gid _ <<<"$l"
        [[ $name =~ ^(sync|shutdown|halt|operator) ]] && continue
        [[ $gid == 0 ]] && hits+=("$name")
    done
    if [[ ${#hits[@]} -eq 1 && ${hits[0]} == root ]]; then
        result "$id" PASS "only root has primary GID 0"
    else
        result "$id" FAIL "accounts with primary GID 0: ${hits[*]:-none}, expected only root"
    fi
}

# 5.4.2.3 Ensure group root is the only GID 0 group.
cus_5_4_2_3() {
    local id=$1 l name gid
    local -a hits=()
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    for l in "${GROUP_L[@]}"; do
        IFS=: read -r name _ gid _ <<<"$l"
        [[ $gid == 0 ]] && hits+=("$name")
    done
    if [[ ${#hits[@]} -eq 1 && ${hits[0]} == root ]]; then
        result "$id" PASS "only group root has GID 0"
    else
        result "$id" FAIL "groups with GID 0: ${hits[*]:-none}, expected only root"
    fi
}

# 5.4.2.4 Ensure root account access is controlled: the root password is set (P) or
# the account is locked (L). passwd -S is not run; the status comes from /etc/shadow
# the same way passwd prints it (* or ! prefix = L, empty = NP).
shadow_status() { # shadow_status <password field> -> REPLY P|L|NP
    case $1 in
        '') REPLY=NP ;;
        '*'*|'!'*) REPLY=L ;;
        *) REPLY=P ;;
    esac
}
cus_5_4_2_4() {
    local id=$1 l name pw
    need shadow || return
    for l in "${SHADOW_L[@]}"; do
        IFS=: read -r name pw _ <<<"$l"
        if [[ $name == root ]]; then
            shadow_status "$pw"
            if [[ $REPLY == P || $REPLY == L ]]; then
                result "$id" PASS "root password status: $REPLY (P = password set, L = locked)"
            else
                result "$id" FAIL "root password status: NP (no password set), expected P or L"
            fi
            return
        fi
    done
    result "$id" FAIL "root has no entry in /etc/shadow"
}

# 5.4.2.5 Ensure root path integrity: root's PATH has no empty entry, trailing colon,
# '.', and every element is a root-owned directory with no group/other write.
cus_5_4_2_5() {
    local id=$1 rp el
    local -a bad=() ok=() elems
    _need_fact root_path || { result "$id" ERROR "root PATH unavailable: $NEED_ERR"; return; }
    rp=$(head -n1 "$FACT_FILE")
    [[ $rp == *::* ]] && bad+=("root's PATH contains an empty directory (::)")
    [[ $rp == *: ]] && bad+=("root's PATH contains a trailing colon")
    [[ ":$rp:" == *:.:* ]] && bad+=("root's PATH contains the current working directory (.)")
    IFS=':' read -ra elems <<<"$rp"
    for el in "${elems[@]}"; do
        [[ -z $el || $el == . ]] && continue
        if ! fstat "$el" || [[ $S_TYPE != d ]]; then
            bad+=("\"$el\" is not a directory")
            continue
        fi
        [[ $S_USER == root ]] || bad+=("directory $el is owned by $S_USER, expected root")
        if (( 8#$S_MODE & 8#0022 )); then
            bad+=("directory $el is mode $S_MODE4, expected 0755 or more restrictive")
        fi
    done
    (( ${#bad[@]} )) || ok+=("root PATH $rp: all elements are root-owned directories, mode 0755 or stricter")
    if (( ${#bad[@]} )); then result "$id" FAIL "${bad[@]}" "root PATH: $rp"; else result "$id" PASS "${ok[@]}"; fi
}

# 5.4.2.6 Ensure root user umask is configured: no umask less restrictive than 0027
# in /root/.profile and /root/.bashrc (the PDF's regular expression).
cus_5_4_2_6() {
    local id=$1 f hits
    local -a bad=() seen=()
    local rx='^\s*umask\s+((\d{1,2}(\d[^7]|[^2-7]\d)\b)|(u=[rwx]{1,3},)?(((g=[rx]?[rx]?w[rx]?[rx]?\b)(,o=[rwx]{1,3})?)|((g=[wrx]{1,3},)?o=[wrx]{1,3}\b)))'
    for f in /root/.profile /root/.bashrc; do
        [[ -r $R$f ]] || continue
        seen+=("$f")
        hits=$(grep -Pi -- "$rx" "$R$f")
        [[ -n $hits ]] && bad+=("$f: ${hits//$'\n'/ | }, less restrictive than umask 027")
    done
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}"
    else
        result "$id" PASS "no umask less restrictive than 027 in ${seen[*]:-/root/.profile or /root/.bashrc (files do not exist)}"
    fi
}

# 5.4.2.7 Ensure system accounts do not have a valid login shell: accounts with
# UID below UID_MIN (or 65534), except root halt sync shutdown nfsnobody.
cus_5_4_2_7() {
    local id=$1 l name uid shell umin
    local -a bad=()
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    login_defs_get UID_MIN && umin=$REPLY || umin=1000
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r name _ uid _ _ _ shell <<<"$l"
        [[ $name =~ ^(root|halt|sync|shutdown|nfsnobody)$ ]] && continue
        is_uint "$uid" || continue
        if (( uid < umin || uid == 65534 )) && [[ -n ${VALID_SHELL[$shell]+x} ]]; then
            bad+=("service account \"$name\" (UID $uid) has a valid shell: $shell")
        fi
    done
    cap_lines 25 "${bad[@]}"
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${CAPPED[@]}"
    else
        result "$id" PASS "no system account (UID below $umin) has a valid login shell"
    fi
}

# 5.4.2.8 Ensure accounts without a valid login shell are locked.
cus_5_4_2_8() {
    local id=$1 l name pw shell sh_of
    local -a bad=()
    local -A shell_of=()
    need shadow || return
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r name _ _ _ _ _ shell <<<"$l"
        shell_of[$name]=$shell
    done
    for l in "${SHADOW_L[@]}"; do
        IFS=: read -r name pw _ <<<"$l"
        [[ $name == root ]] && continue
        [[ -n ${shell_of[$name]+x} ]] || continue
        [[ -n ${VALID_SHELL[${shell_of[$name]}]+x} ]] && continue
        shadow_status "$pw"
        [[ $REPLY == L ]] || bad+=("Account \"$name\" does not have a valid login shell (${shell_of[$name]:-none}) and is not locked")
    done
    cap_lines 25 "${bad[@]}"
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${CAPPED[@]}"
    else
        result "$id" PASS "every non-root account without a valid login shell is locked"
    fi
}

# ---- 5.4.3 shell environment ------------------------------------------------
# 5.4.3.2 Ensure default user shell timeout is configured.
# For every file that mentions TMOUT (/etc/*bashrc, /etc/profile, /etc/profile.d/*.sh):
# TMOUT=N with 0 < N <= 900, readonly and exported in the same file. The check
# passes when at least one file is complete and no file sets TMOUT incorrectly.
cus_5_4_3_2() {
    local id=$1 f max v ro ex good=0 vals
    local -a bad=() ok=() files=()
    site_val TMOUT_MAX 900; max=$REPLY
    shopt -s nullglob
    for f in "$R"/etc/*bashrc "$R/etc/profile" "$R"/etc/profile.d/*.sh; do
        [[ -f $f ]] && files+=("${f#"$R"}")
    done
    shopt -u nullglob
    for f in "${files[@]}"; do
        grep -Pqs -- '^([^#\n\r]+)?\bTMOUT\b' "$R$f" || continue
        vals=$(grep -Po -- '^([^#\n\r]+)?\bTMOUT=\K[0-9]+' "$R$f")
        ro=$(grep -P -- '^\s*(typeset\s-xr\sTMOUT=\d+|([^#\n\r]+)?\breadonly\s+TMOUT\b)' "$R$f")
        ex=$(grep -P -- '^\s*(typeset\s-xr\sTMOUT=\d+|([^#\n\r]+)?\bexport\b([^#\n\r]+\b)?TMOUT\b)' "$R$f")
        if [[ -z $vals ]]; then
            bad+=("$f: TMOUT is mentioned but not assigned a value in this file")
            continue
        fi
        local fileok=1
        for v in $vals; do
            if (( v > max || v <= 0 )); then
                bad+=("$f: TMOUT=$v, expected 1 to $max")
                fileok=0
            fi
        done
        [[ -n $ro ]] || { bad+=("$f: TMOUT is not marked readonly"); fileok=0; }
        [[ -n $ex ]] || { bad+=("$f: TMOUT is not exported"); fileok=0; }
        if (( fileok )); then ok+=("$f: TMOUT=${vals//$'\n'/,}, readonly and exported"); good=1; fi
    done
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    elif (( good )); then
        result "$id" PASS "${ok[@]}"
    else
        result "$id" FAIL "TMOUT is not configured in ${files[*]:-/etc/profile, /etc/profile.d/*.sh or /etc/bashrc}, expected readonly exported TMOUT of at most $max seconds"
    fi
}

# 5.4.3.3 Ensure default user umask is configured: no umask less restrictive than 027
# in /etc/profile, /etc/profile.d/*.sh and /etc/bash.bashrc, and UMASK in login.defs.
# (The PDF names /etc/profile.d/ as a directory without -r; the files in it are checked.)
cus_5_4_3_3() {
    local id=$1 f hits
    local -a bad=() seen=()
    glob_files '/etc/profile' '/etc/profile.d/*.sh' '/etc/bash.bashrc'
    for f in "${GLOB[@]}"; do
        seen+=("$f")
        # \s++ is possessive: with plain \s+ the engine backtracks into the blanks and
        # reports a compliant "umask   027" (the PDF's regex has this flaw)
        hits=$(grep -Psi -- '^\s*umask\s++(?!0?[02367]7\b)' "$R$f")
        [[ -n $hits ]] && bad+=("$f: ${hits//$'\n'/ | }, expected 027 or more restrictive")
    done
    hits=$(grep -Psi -- '^\s*UMASK\s++(?!0?[02367]7\b)' "$R/etc/login.defs" 2>/dev/null)
    [[ -n $hits ]] && bad+=("/etc/login.defs: ${hits//$'\n'/ | }, expected 027 or more restrictive")
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}"
    else
        result "$id" PASS "no umask less restrictive than 027 in ${seen[*]} or /etc/login.defs"
    fi
}

man_ev_5_1_14() {
    if need_sshd; then
        local k=${SSHD[base:kexalgorithms]-}
        printf 'kexalgorithms: %s\n' "$k"
        [[ ,$k, == *,sntrup761x25519-sha512*,* || $k == *sntrup761x25519-sha512* ]] && printf 'sntrup761x25519-sha512 is offered\n' || printf 'sntrup761x25519-sha512 is NOT offered\n'
        [[ $k == *mlkem768x25519-sha256* ]] && printf 'mlkem768x25519-sha256 is offered\n' || printf 'mlkem768x25519-sha256 is NOT offered (required from OpenSSH 9.9)\n'
    fi
}

man_ev_5_3_3_2_3() {
    local f
    glob_files '/etc/security/pwquality.conf' '/etc/security/pwquality.conf.d/*.conf'
    for f in "${GLOB[@]}"; do
        grep -Psi -- '^\s*(minclass|[dulo]credit)\b' "$R$f" | sed "s|^|$f: |"
    done
    return 0
}

# ==== lib/checks_custom/s6_logging.sh ====
# lib/checks_custom/s6_logging.sh - custom checks, benchmark section 6.
# shellcheck disable=SC2034,SC2154

# rsyslog_files: RSYS = /etc/rsyslog.conf plus /etc/rsyslog.d/*.conf that exist
rsyslog_files() {
    RSYS=()
    local f
    [[ -r $R/etc/rsyslog.conf ]] && RSYS+=("/etc/rsyslog.conf")
    shopt -s nullglob
    local -a d
    mapfile -t d < <(printf '%s\n' "$R"/etc/rsyslog.d/*.conf | LC_ALL=C sort)
    shopt -u nullglob
    for f in "${d[@]}"; do [[ -n $f ]] && RSYS+=("${f#"$R"}"); done
}

# 6.1.2.3 Ensure rsyslog log file creation mode is configured: a $FileCreateMode of
# 0640 or more restrictive; without the directive the default 0644 applies.
cus_6_1_2_3() {
    local id=$1 f line val ex
    local -a bad=() ok=()
    rsyslog_files
    for f in "${RSYS[@]}"; do
        while IFS= read -r line; do
            val=$(grep -Po -- '\$FileCreateMode\s+\K0[0-7]{3}' <<<"$line")
            if oct_excess "$val" 640; then
                ok+=("$f: \$FileCreateMode $val")
            else
                bad+=("$f: \$FileCreateMode $val grants $OCT_EX beyond 0640")
            fi
        done < <(grep -Psi -- '^\s*\$FileCreateMode\s+0[0-7]{3}\b' "$R$f")
    done
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    elif (( ${#ok[@]} == 0 )); then
        result "$id" FAIL "no \$FileCreateMode directive in /etc/rsyslog.conf or /etc/rsyslog.d/*.conf; the default 0644 applies, expected 0640 or more restrictive"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

# 6.1.2.6 Ensure rsyslog is not configured to receive logs from a remote client:
# no imtcp / imudp module or input in advanced or legacy format.
cus_6_1_2_6() {
    local id=$1 f rx
    local -a bad=() rxs=(
        '^\s*module\(load="?imtcp"?\)' '^\s*input\(type="?imtcp"?\b'
        '^\s*module\(load="?imudp"?\)' '^\s*input\(type="?imudp"?\b'
        '^\s*\$ModLoad\s+imtcp\b' '^\s*\$InputTCPServerRun\b'
        '^\s*\$ModLoad\s+imudp\b' '^\s*\$UDPServerRun\b')
    rsyslog_files
    for f in "${RSYS[@]}"; do
        for rx in "${rxs[@]}"; do
            while IFS= read -r line; do
                bad+=("$f: $line")
            done < <(grep -Psi -- "$rx" "$R$f")
        done
    done
    if (( ${#bad[@]} )); then
        result "$id" FAIL "rsyslog is set up to receive remote logs:" "${bad[@]}"
    else
        result "$id" PASS "no imtcp/imudp module or input (advanced or legacy format) in ${RSYS[*]:-the rsyslog configuration}"
    fi
}

# 6.1.3.1 Ensure access to all logfiles has been configured.
# Port of the PDF script (tools/reference/cis_6.1.3.1_audit.sh): the fact logfiles
# lists the files the PDF's find reports; the per-file mask and the allowed
# owner/group depend on the file name. Owner/group alternatives are matched in full.
cus_6_1_3_1() {
    local id=$1 mode user group path base mask auser agroup sh maxo
    local -a bad=() sub
    local -A shell_of=()
    _need_fact logfiles || { result "$id" ERROR "log file list unavailable: $NEED_ERR"; return; }
    acct_load || { result "$id" ERROR "cannot read /etc/passwd: $NEED_ERR"; return; }
    local l
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r u _ _ _ _ _ sh <<<"$l"
        shell_of[$u]=$sh
    done
    local -A etc_shell=()
    if [[ -r $R/etc/shells ]]; then
        while IFS= read -r l; do [[ $l == /* ]] && etc_shell[$l]=1; done <"$R/etc/shells"
    fi
    while IFS=$'\t' read -r mode user group path; do
        [[ -n $path ]] || continue
        base=${path##*/}
        if [[ ${path%/*} =~ /apt[[:space:]]*$ ]]; then
            mask=0133 auser="root" agroup="root|adm"
        else
            case $base in
                lastlog|lastlog.*|wtmp|wtmp.*|wtmp-*|btmp|btmp.*|btmp-*|README)
                    mask=0113 auser="root" agroup="root|utmp" ;;
                cloud-init.log*|localmessages*|waagent.log*)
                    mask=0133 auser="root|syslog" agroup="root|adm" ;;
                secure|secure.*|secure-*|auth.log|syslog|messages)
                    mask=0137 auser="root|syslog" agroup="root|adm" ;;
                SSSD|sssd)
                    mask=0117 auser="root|SSSD" agroup="root|SSSD" ;;
                gdm|gdm3)
                    mask=0117 auser="root" agroup="root|gdm|gdm3" ;;
                *.journal|*.journal~)
                    mask=0137 auser="root" agroup="root|systemd-journal" ;;
                *)
                    mask=0137 auser="root|syslog" agroup="root|adm"
                    sh=${shell_of[$user]-}
                    # files of service accounts (no valid login shell) may belong to that account
                    if [[ $user == root ]] || [[ -n ${shell_of[$user]+x} && -z ${etc_shell[$sh]+x} ]]; then
                        list_has "$auser" "$user" || auser="root|syslog|$user"
                        list_has "$agroup" "$group" || agroup="root|adm|$group"
                    fi ;;
            esac
        fi
        sub=()
        printf -v maxo '%o' $((0777 & ~8#$mask))
        if ! oct_excess "$mode" "$maxo"; then
            mode4 "$mode"
            printf -v maxo '%04o' $((0777 & ~8#$mask))
            sub+=("mode $M4 should be $maxo or more restrictive")
        fi
        list_has "$auser" "$user" || sub+=("owned by $user, should be ${auser//|/ or }")
        list_has "$agroup" "$group" || sub+=("group owned by $group, should be ${agroup//|/ or }")
        (( ${#sub[@]} )) && bad+=("$path: $(IFS=';'; echo "${sub[*]}")")
    done <"$FACT_FILE"
    cap_lines 30 "${bad[@]}"
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${CAPPED[@]}"
    else
        result "$id" PASS "all files in /var/log have appropriate permissions and ownership"
    fi
}

# 6.3.2 Ensure filesystem integrity is regularly checked: dailyaidecheck.timer enabled
# and active, dailyaidecheck.service static or enabled.
cus_6_3_2() {
    local id=$1 ts ss
    local -a bad=() ok=()
    need units || return
    ts=${UNIT_FILE_STATE[dailyaidecheck.timer]-not found}
    ss=${UNIT_FILE_STATE[dailyaidecheck.service]-not found}
    [[ $ts == enabled ]] && ok+=("dailyaidecheck.timer is enabled") || bad+=("dailyaidecheck.timer: $ts, expected enabled")
    [[ $ss == static || $ss == enabled ]] && ok+=("dailyaidecheck.service is $ss") || bad+=("dailyaidecheck.service: $ss, expected static or enabled")
    if unit_is_active dailyaidecheck.timer; then ok+=("dailyaidecheck.timer is active"); else bad+=("dailyaidecheck.timer is not active"); fi
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}" "${ok[@]}"
    else
        result "$id" PASS "${ok[@]}"
    fi
}

man_ev_6_1_1_1_4() {
    local f
    for f in /etc/tmpfiles.d/systemd.conf /usr/lib/tmpfiles.d/systemd.conf; do
        [[ -r $R$f ]] || continue
        local type path perm rest
        while read -r type path perm rest; do
            [[ $type == f && $perm =~ ^0?[0-7]{3,4}$ ]] || continue
            fexists "$path" || continue
            (( 8#$S_MODE & 8#0137 )) && printf '%s: mode %s grants more than 0640 (defined in %s)\n' "$path" "$S_MODE4" "$f"
        done <"$R$f"
    done
    return 0
}

man_ev_6_1_1_1_5() {
    local f
    glob_files '/etc/systemd/journald.conf' '/etc/systemd/journald.conf.d/*.conf'
    for f in "${GLOB[@]}"; do
        grep -Psi -- '\b(SystemMaxUse|SystemKeepFree|RuntimeMaxUse|RuntimeKeepFree|MaxFileSec)=' "$R$f" | sed "s|^|$f: |"
    done
    return 0
}

man_ev_6_1_2_4() {
    rsyslog_files
    printf 'rsyslog configuration files: %s\n' "${RSYS[*]:-none}"
}

man_ev_6_1_2_5() {
    local f hits
    rsyslog_files
    for f in "${RSYS[@]}"; do
        hits=$(grep -Psi -- '^\s*\*\.\*\s+@{1,2}\S+' "$R$f"; grep -Psi -- 'target="?[^#"[:space:]]+' "$R$f" | head -n 3)
        [[ -n $hits ]] && printf '%s: %s\n' "$f" "${hits//$'\n'/ | }"
    done
    return 0
}

man_ev_6_1_2_7() {
    printf 'logrotate configuration: %s\n' "$( [[ -r $R/etc/logrotate.conf ]] && echo /etc/logrotate.conf present || echo missing)"
}

# ==== lib/checks_custom/s7_maintenance.sh ====
# lib/checks_custom/s7_maintenance.sh - custom checks, benchmark section 7.
# shellcheck disable=SC2034,SC2154

# 7.1.11 Ensure world writable files and directories are secured.
# Port of tools/reference/cis_7.1.11_audit.sh: the fact fs_world holds world-writable
# files (f) and world-writable directories without the sticky bit (d), found with
# -xdev on local mounts only (run/tmp/var/tmp and network or pseudo filesystems skipped).
cus_7_1_11() {
    local id=$1 kind path
    local -a files=() dirs=()
    _need_fact fs_world || { result "$id" ERROR "filesystem walk failed or timed out: $NEED_ERR (raise --timeout)"; return; }
    while IFS=$'\t' read -r kind path; do
        case $kind in f) files+=("$path") ;; d) dirs+=("$path") ;; esac
    done <"$FACT_FILE"
    local -a ev=()
    if (( ${#files[@]} )); then
        cap_lines 20 "${files[@]}"
        ev+=("${#files[@]} world writable files, expected none:" "${CAPPED[@]}")
    fi
    if (( ${#dirs[@]} )); then
        cap_lines 20 "${dirs[@]}"
        ev+=("${#dirs[@]} world writable directories without the sticky bit, expected none:" "${CAPPED[@]}")
    fi
    if (( ${#ev[@]} )); then
        result "$id" FAIL "${ev[@]}"
    else
        result "$id" PASS "no world writable files and no world writable directories without the sticky bit on local filesystems"
    fi
}

# 7.1.12 Ensure no files or directories without an owner and a group exist.
cus_7_1_12() {
    local id=$1 kind path
    local -a nu=() ng=() ev=()
    _need_fact fs_nouser || { result "$id" ERROR "filesystem walk failed or timed out: $NEED_ERR (raise --timeout)"; return; }
    while IFS=$'\t' read -r kind path; do
        case $kind in u) nu+=("$path") ;; g) ng+=("$path") ;; esac
    done <"$FACT_FILE"
    if (( ${#nu[@]} )); then cap_lines 20 "${nu[@]}"; ev+=("${#nu[@]} files or directories without an owner, expected none:" "${CAPPED[@]}"); fi
    if (( ${#ng[@]} )); then cap_lines 20 "${ng[@]}"; ev+=("${#ng[@]} files or directories without a group, expected none:" "${CAPPED[@]}"); fi
    if (( ${#ev[@]} )); then
        result "$id" FAIL "${ev[@]}"
    else
        result "$id" PASS "no files or directories without an owner or a group exist on local filesystems"
    fi
}

man_ev_7_1_13() {
    local kind path ns=0 ng=0 shown=0 approved=""
    if ! _need_fact fs_suid; then
        printf 'SUID/SGID list unavailable: %s\n' "$NEED_ERR"
        return
    fi
    [[ -n ${SITE[APPROVED_SUID_FILE]-} && -r $R${SITE[APPROVED_SUID_FILE]} ]] && approved=$R${SITE[APPROVED_SUID_FILE]}
    while IFS=$'\t' read -r kind path; do
        [[ $kind == suid ]] && ns=$((ns + 1))
        [[ $kind == sgid ]] && ng=$((ng + 1))
        if [[ -n $approved ]] && grep -qxF -- "$path" "$approved"; then continue; fi
        if (( shown < 40 )); then
            printf '%s: %s\n' "$kind" "$path"
            shown=$((shown + 1))
        fi
    done <"$FACT_FILE"
    printf '%d SUID and %d SGID files found%s\n' "$ns" "$ng" "${approved:+ (files in APPROVED_SUID_FILE are not listed above)}"
}

# ---- 7.2 local user and group settings --------------------------------------
# 7.2.1 Ensure accounts in /etc/passwd use shadowed passwords.
cus_7_2_1() {
    local id=$1 l name pw
    local -a bad=()
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r name pw _ <<<"$l"
        [[ $pw != x ]] && bad+=("User \"$name\" is not set to shadowed passwords (password field is '${pw:-empty}')")
    done
    if (( ${#bad[@]} )); then result "$id" FAIL "${bad[@]}"; else result "$id" PASS "all accounts in /etc/passwd use 'x' (shadowed passwords)"; fi
}

# 7.2.2 Ensure /etc/shadow password fields are not empty.
cus_7_2_2() {
    local id=$1 l name pw
    local -a bad=()
    need shadow || return
    for l in "${SHADOW_L[@]}"; do
        IFS=: read -r name pw _ <<<"$l"
        [[ -z $pw ]] && bad+=("$name does not have a password")
    done
    if (( ${#bad[@]} )); then result "$id" FAIL "${bad[@]}"; else result "$id" PASS "no account has an empty password field in /etc/shadow"; fi
}

# 7.2.3 Ensure all groups in /etc/passwd exist in /etc/group.
cus_7_2_3() {
    local id=$1 l name gid
    local -a bad=()
    local -A gids=()
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    for l in "${GROUP_L[@]}"; do
        IFS=: read -r _ _ gid _ <<<"$l"
        gids[$gid]=1
    done
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r name _ _ gid _ <<<"$l"
        [[ -n ${gids[$gid]+x} ]] || bad+=("User \"$name\" has GID \"$gid\" which does not exist in /etc/group")
    done
    if (( ${#bad[@]} )); then result "$id" FAIL "${bad[@]}"; else result "$id" PASS "every primary GID in /etc/passwd exists in /etc/group"; fi
}

# 7.2.4 Ensure shadow group is empty: no members and no user with it as primary group.
cus_7_2_4() {
    local id=$1 l name gid members sgid=""
    local -a bad=()
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    for l in "${GROUP_L[@]}"; do
        IFS=: read -r name _ gid members <<<"$l"
        if [[ $name == shadow ]]; then
            sgid=$gid
            [[ -n $members ]] && bad+=("group shadow has members: $members")
        fi
    done
    if [[ -n $sgid ]]; then
        for l in "${PASSWD_L[@]}"; do
            IFS=: read -r name _ _ gid _ <<<"$l"
            [[ $gid == "$sgid" ]] && bad+=("user \"$name\" has the shadow group as primary group")
        done
    fi
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${bad[@]}"
    elif [[ -z $sgid ]]; then
        result "$id" PASS "there is no shadow group"
    else
        result "$id" PASS "group shadow (GID $sgid) has no members and is no user's primary group"
    fi
}

# dup_check <file-lines-array-name> <field> <label> ... prints duplicates
dup_report() { # dup_report <"u"|"g"> <field index (1 name, 3 id)> <label>
    local -n src=$1
    local field=$2 label=$3 l key name
    local -A count=() names=()
    DUPS=()
    for l in "${src[@]}"; do
        IFS=: read -ra fld <<<"$l"
        key=${fld[$((field - 1))]}
        name=${fld[0]}
        count[$key]=$(( ${count[$key]:-0} + 1 ))
        names[$key]+="$name "
    done
    for key in "${!count[@]}"; do
        (( count[$key] > 1 )) && DUPS+=("Duplicate $label: \"$key\" ${field/3/Names}: \"${names[$key]% }\"")
    done
    return 0
}

# 7.2.5 Ensure no duplicate UIDs exist.
cus_7_2_5() {
    need acct || { result "$1" ERROR "cannot read account files: $NEED_ERR"; return; }
    dup_report PASSWD_L 3 UID
    if (( ${#DUPS[@]} )); then result "$1" FAIL "${DUPS[@]}"; else result "$1" PASS "no UID is used by more than one account"; fi
}
# 7.2.6 Ensure no duplicate GIDs exist.
cus_7_2_6() {
    need acct || { result "$1" ERROR "cannot read account files: $NEED_ERR"; return; }
    dup_report GROUP_L 3 GID
    if (( ${#DUPS[@]} )); then result "$1" FAIL "${DUPS[@]}"; else result "$1" PASS "no GID is used by more than one group"; fi
}
# 7.2.7 Ensure no duplicate user names exist.
cus_7_2_7() {
    need acct || { result "$1" ERROR "cannot read account files: $NEED_ERR"; return; }
    dup_report PASSWD_L 1 "user name"
    if (( ${#DUPS[@]} )); then result "$1" FAIL "${DUPS[@]}"; else result "$1" PASS "no user name appears more than once in /etc/passwd"; fi
}
# 7.2.8 Ensure no duplicate group names exist.
cus_7_2_8() {
    need acct || { result "$1" ERROR "cannot read account files: $NEED_ERR"; return; }
    dup_report GROUP_L 1 "group name"
    if (( ${#DUPS[@]} )); then result "$1" FAIL "${DUPS[@]}"; else result "$1" PASS "no group name appears more than once in /etc/group"; fi
}

# 7.2.9 Ensure local interactive user home directories are configured: the directory
# exists, is owned by the user and is mode 0750 or more restrictive.
cus_7_2_9() {
    local id=$1 l name home shell n=0
    local -a bad=()
    need acct || { result "$id" ERROR "cannot read account files: $NEED_ERR"; return; }
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r name _ _ _ _ home shell <<<"$l"
        [[ -n ${VALID_SHELL[$shell]+x} ]] || continue
        n=$((n + 1))
        if ! fstat "$home" || [[ $S_TYPE != d ]]; then
            bad+=("User \"$name\" home directory \"$home\" doesn't exist")
            continue
        fi
        [[ $S_USER == "$name" ]] || bad+=("User \"$name\" home \"$home\" is owned by \"$S_USER\"")
        (( 8#$S_MODE & 8#0027 )) && bad+=("User \"$name\" home \"$home\" is mode $S_MODE4, should be 0750 or more restrictive")
    done
    cap_lines 30 "${bad[@]}"
    if (( ${#bad[@]} )); then
        result "$id" FAIL "${CAPPED[@]}"
    else
        result "$id" PASS "$n interactive users: all home directories exist, are owned by the user and are mode 0750 or stricter"
    fi
}

# primary_group_of <user> -> REPLY
primary_group_of() {
    local l name gid g gname ggid
    REPLY=""
    for l in "${PASSWD_L[@]}"; do
        IFS=: read -r name _ _ gid _ <<<"$l"
        if [[ $name == "$1" ]]; then
            for g in "${GROUP_L[@]}"; do
                IFS=: read -r gname _ ggid _ <<<"$g"
                [[ $ggid == "$gid" ]] && { REPLY=$gname; return 0; }
            done
        fi
    done
    return 1
}

REMOTE_FS="nfs nfs4 cifs smbfs smb3 fuse.sshfs afs ncpfs glusterfs ceph"

# home_dot_scan <f|d> -> HD_BAD, HD_WARN, HD_SKIP, HD_USERS
# Reads the home_dots fact: "home user path fstype" lines, then "kind user mode owner group path".
home_dot_scan() {
    local want=$1 kind user a b c d mask max pg t
    HD_BAD=() HD_WARN=() HD_SKIP=() HD_USERS=0
    _need_fact home_dots || return 1
    acct_load || return 1
    # first pass: "home <user> <path> <fstype>" lines; homes on remote filesystems are skipped
    local -A remote=()
    while IFS=$'\t' read -r kind user a b; do
        [[ $kind == home ]] || continue
        HD_USERS=$((HD_USERS + 1))
        for t in $REMOTE_FS; do
            if [[ $b == "$t" ]]; then
                remote[$user]=1
                HD_SKIP+=("User \"$user\" home \"$a\" skipped (remote/network filesystem: $b)")
            fi
        done
    done <"$FACT_FILE"
    local name base
    while IFS=$'\t' read -r kind user a b c d; do
        [[ $kind == "$want" ]] || continue
        [[ -n ${remote[$user]+x} ]] && continue
        # a = mode, b = owner, c = group, d = path
        base=${d##*/}
        if [[ $want == f ]]; then
            case $base in
                .forward|.rhosts) HD_BAD+=("User \"$user\": file \"$d\" exists"); continue ;;
                .netrc|.bash_history) mask=0177 ;;
                *) mask=0133 ;;
            esac
        else
            case $base in .ssh) mask=0077 ;; *) mask=0027 ;; esac
        fi
        primary_group_of "$user" && pg=$REPLY || pg=""
        local -a sub=()
        max=$(printf '%04o' $((0777 & ~8#$mask)))
        if (( 8#$a & 8#$mask )); then mode4 "$a"; sub+=("is mode $M4 and should be mode $max or more restrictive"); fi
        [[ $b == "$user" ]] || sub+=("owned by \"$b\" and should be owned by \"$user\"")
        [[ -z $pg || $c == "$pg" ]] || sub+=("group owned by \"$c\" and should be group owned by \"$pg\"")
        if (( ${#sub[@]} )); then
            HD_BAD+=("User \"$user\": \"$d\" $(IFS=';'; echo "${sub[*]}")")
        elif [[ $base == .netrc ]]; then
            HD_WARN+=("User \"$user\": file \"$d\" exists (mode and owner are fine; confirm it follows site policy)")
        fi
    done <"$FACT_FILE"
    return 0
}

# 7.2.10 Ensure local interactive user dot files access is configured: no .forward,
# .rhosts; .netrc and .bash_history 0600 or stricter; other dot files 0644 or stricter;
# owned by the user and group-owned by the user's primary group.
cus_7_2_10() {
    local id=$1
    if ! home_dot_scan f; then
        result "$id" ERROR "home directory scan unavailable: ${NEED_ERR:-fact home_dots missing}"
        return
    fi
    cap_lines 30 "${HD_BAD[@]}"
    if (( ${#HD_BAD[@]} )); then
        result "$id" FAIL "${CAPPED[@]}" "${HD_WARN[@]}" "${HD_SKIP[@]}"
    else
        result "$id" PASS "dot files of $HD_USERS local interactive users are configured correctly" "${HD_WARN[@]}" "${HD_SKIP[@]}"
    fi
}

# 7.2.11 Ensure local interactive user dot directories access is configured:
# dot directories 0750 or stricter, .ssh 0700 or stricter, owned by the user and
# group-owned by the user's primary group.
cus_7_2_11() {
    local id=$1
    if ! home_dot_scan d; then
        result "$id" ERROR "home directory scan unavailable: ${NEED_ERR:-fact home_dots missing}"
        return
    fi
    cap_lines 30 "${HD_BAD[@]}"
    if (( ${#HD_BAD[@]} )); then
        result "$id" FAIL "${CAPPED[@]}" "${HD_SKIP[@]}"
    else
        result "$id" PASS "dot directories of $HD_USERS local interactive users are configured correctly" "${HD_SKIP[@]}"
    fi
}

# ==== lib/exceptions.sh ====
# lib/exceptions.sh - site.conf and exceptions.conf parsing and exception handling.
#
# Both files are parsed line by line as data. They are never sourced or eval'ed:
# the script runs as root. Unknown keys, bad syntax, values weaker than the
# benchmark, or an exception for an unknown control stop the run with exit code 3,
# so a typo cannot silently weaken the audit.
# shellcheck disable=SC2034

# key -> rule. Benchmark values are copied from the PDF; the control ID is the
# place to verify them (also cited in etc/site.conf.example).
declare -A SITE_RULE=(
    [BANNER_FILE]="path"
    [TIME_DAEMON]="enum:auto,chrony,timesyncd"
    [LOGGER]="enum:auto,journald,rsyslog"
    [APPROVED_LISTENERS]="text"
    [APPROVED_SUID_FILE]="path"
    [SSH_ALLOW_DIRECTIVE_REQUIRED]="enum:1"        # 5.1.5
    [PASS_MAX_DAYS]="max:365:1"                    # 5.4.1.1
    [PASS_WARN_AGE]="min:7"                        # 5.4.1.3
    [INACTIVE]="max:45:0"                          # 5.4.1.5
    [PWQ_MINLEN]="min:14"                          # 5.3.3.2.2
    [PWQ_DIFOK]="min:2"                            # 5.3.3.2.1
    [FAILLOCK_DENY]="max:5:1"                      # 5.3.3.1.1
    [FAILLOCK_UNLOCK_TIME]="zmin:900"              # 5.3.3.1.2
    [PWHISTORY_REMEMBER]="min:24"                  # 5.3.3.3.1
    [TMOUT_MAX]="max:900:1"                        # 5.4.3.2
    [SSH_MAX_AUTH_TRIES]="max:4:1"                 # 5.1.18
    [SSH_MAX_SESSIONS]="max:10:1"                  # 5.1.19
    [SSH_LOGIN_GRACE_TIME]="max:60:1"              # 5.1.15
)

site_load() {
    local file=$1 line n=0 key val rule
    [[ -r $file ]] || die_usage "site configuration $file is not readable"
    while IFS= read -r line || [[ -n $line ]]; do
        n=$((n + 1))
        line=${line%$'\r'}
        trim "$line"
        line=$REPLY
        [[ -z $line || $line == \#* ]] && continue
        if [[ ! $line =~ ^([A-Z][A-Z0-9_]*)=(.*)$ ]]; then
            die_usage "$file:$n: syntax error (expected KEY=value)"
        fi
        key=${BASH_REMATCH[1]} val=${BASH_REMATCH[2]}
        val=${val%%[[:space:]]#*}            # inline comment
        trim "$val"
        val=$REPLY
        val=${val#\"}
        val=${val%\"}
        if [[ -z ${SITE_RULE[$key]+x} ]]; then
            die_usage "$file:$n: unknown key $key"
        fi
        rule=${SITE_RULE[$key]}
        case $rule in
            path)
                [[ $val == /* ]] || die_usage "$file:$n: $key must be an absolute path" ;;
            text) ;;
            enum:*)
                list_has "${rule#enum:}" "$val" || die_usage "$file:$n: $key must be one of ${rule#enum:} (got '$val')" ;;
            max:*)
                is_uint "$val" || die_usage "$file:$n: $key must be a number"
                local mx=${rule#max:} mn
                mn=${mx#*:} mx=${mx%%:*}
                (( val >= mn )) || die_usage "$file:$n: $key=$val is below the minimum $mn"
                (( val <= mx )) || die_usage "$file:$n: $key=$val is weaker than the benchmark value $mx; record an accepted deviation in the exceptions file instead" ;;
            min:*)
                is_uint "$val" || die_usage "$file:$n: $key must be a number"
                (( val >= ${rule#min:} )) || die_usage "$file:$n: $key=$val is weaker than the benchmark value ${rule#min:}; record an accepted deviation in the exceptions file instead" ;;
            zmin:*)
                is_uint "$val" || die_usage "$file:$n: $key must be a number"
                (( val == 0 || val >= ${rule#zmin:} )) || die_usage "$file:$n: $key=$val is weaker than the benchmark value ${rule#zmin:} (0 means never); record an accepted deviation in the exceptions file instead" ;;
        esac
        SITE[$key]=$val
    done <"$file"
}

# exceptions_load <file>; ids are validated against the full catalog.
exceptions_load() {
    local file=$1 line n=0 id just by exp
    [[ -r $file ]] || die_usage "exceptions file $file is not readable"
    while IFS= read -r line || [[ -n $line ]]; do
        n=$((n + 1))
        line=${line%$'\r'}
        trim "$line"
        line=$REPLY
        [[ -z $line || $line == \#* ]] && continue
        local bars=${line//[^|]/}
        (( ${#bars} == 3 )) || die_usage "$file:$n: expected exactly 3 '|' separators (no '|' inside the text)"
        IFS='|' read -r id just by exp <<<"$line"
        trim "$id";   id=$REPLY
        trim "$just"; just=$REPLY
        trim "$by";   by=$REPLY
        trim "$exp";  exp=$REPLY
        if [[ -z $id || -z $just || -z $by || -z $exp ]] || [[ $line != *'|'*'|'*'|'* ]]; then
            die_usage "$file:$n: expected 'id | justification | approved_by | expires (YYYY-MM-DD)'"
        fi
        if [[ -z ${CAT_TYPE[$id]+x} ]]; then
            die_usage "$file:$n: control $id is not in the catalog"
        fi
        valid_date "$exp" || die_usage "$file:$n: '$exp' is not a valid date (YYYY-MM-DD)"
        if [[ -n ${EXC_JUST[$id]+x} ]]; then
            die_usage "$file:$n: duplicate exception for $id"
        fi
        EXC_JUST[$id]=$just EXC_BY[$id]=$by EXC_EXP[$id]=$exp
    done <"$file"
}

# days_left <YYYY-MM-DD> -> REPLY (negative when expired)
days_left() {
    local d=$1 y m dd t
    y=${d:0:4} m=${d:5:2} dd=${d:8:2}
    days_from_civil "$y" "$m" "$dd"
    t=$REPLY
    days_from_civil "${TODAY:0:4}" "${TODAY:5:2}" "${TODAY:8:2}"
    REPLY=$((t - REPLY))
}

# Exceptions only ever turn FAIL into EXCEPTION. ERROR and MANUAL stay as they are.
exceptions_apply() {
    local id left
    for id in "${!EXC_JUST[@]}"; do
        [[ -n ${R_STATE[$id]+x} ]] || continue          # control not part of this run
        days_left "${EXC_EXP[$id]}"
        left=$REPLY
        case ${R_STATE[$id]} in
            FAIL)
                if (( left >= 0 )); then
                    R_STATE[$id]=EXCEPTION
                    R_NOTE[$id]="exception: ${EXC_JUST[$id]} (approved by ${EXC_BY[$id]}, expires ${EXC_EXP[$id]}, $left days left)"
                else
                    R_NOTE[$id]="exception expired on ${EXC_EXP[$id]} (${EXC_JUST[$id]}, approved by ${EXC_BY[$id]})"
                fi
                ;;
            PASS)
                R_NOTE[$id]="exception no longer needed (${EXC_JUST[$id]})"
                ;;
        esac
    done
}

# ==== lib/report_text.sh ====
# lib/report_text.sh - report model (counts, scores, header data) and the text report.
# The text report is plain ASCII, 100 columns, one line per control, no colour codes.
# shellcheck disable=SC2034

declare -A CNT=() SCNT=()
SECTION_NAMES=([1]="Initial Setup" [2]="Services" [3]="Network" [4]="Host Based Firewall"
    [5]="Access, Authentication and Authorization" [6]="Logging and Auditing" [7]="System Maintenance")
REPORT_STATES=(PASS FAIL EXCEPTION MANUAL N/A SKIPPED ERROR)

# score_str <pass> <fail> -> REPLY like "93.4%" or "n/a"
score_str() {
    local p=$1 f=$2 den=$(($1 + $2)) t
    if (( den == 0 )); then REPLY="n/a"; return; fi
    t=$(( p * 1000 / den ))
    REPLY="$((t / 10)).$((t % 10))%"
}

report_prepare() {
    local id st sec s
    CNT=() SCNT=()
    for s in "${REPORT_STATES[@]}"; do CNT[$s]=0; done
    for id in "${RUN_IDS[@]}"; do
        st=${R_STATE[$id]}
        sec=${id%%.*}
        CNT[$st]=$((CNT[$st] + 1))
        SCNT[$sec:$st]=$(( ${SCNT[$sec:$st]:-0} + 1 ))
        SCNT[$sec:total]=$(( ${SCNT[$sec:total]:-0} + 1 ))
    done
    score_str "${CNT[PASS]}" "${CNT[FAIL]}"
    SCORE_ALL=$REPLY
}

# wrap_lines <width> <first-prefix> <next-prefix> <text>  -> prints wrapped lines
wrap_lines() {
    local width=$1 p1=$2 p2=$3 text=$4 line="" word prefix=$2 room
    local -a words
    read -ra words <<<"$text"
    if (( ${#words[@]} == 0 )); then printf '%s\n' "$p1"; return; fi
    for word in "${words[@]}"; do
        room=$((width - ${#prefix}))
        while (( ${#word} > room )); do
            if [[ -n $line ]]; then
                printf '%s%s\n' "$prefix" "$line"
                line="" prefix=$p2 room=$((width - ${#p2}))
            else
                printf '%s%s\n' "$prefix" "${word:0:room}"
                word=${word:room} prefix=$p2 room=$((width - ${#p2}))
            fi
        done
        if [[ -z $line ]]; then
            line=$word
        elif (( ${#line} + 1 + ${#word} <= room )); then
            line+=" $word"
        else
            printf '%s%s\n' "$prefix" "$line"
            prefix=$p2
            line=$word
        fi
    done
    [[ -n $line ]] && printf '%s%s\n' "$prefix" "$line"
}

text_control_block() { # one control: result line + wrapped evidence
    local id=$1 ev line t
    sanitize "${CAT_TITLE[$id]}"
    t=$REPLY
    trunc "[${R_STATE[$id]}] $id $t" 100
    printf '%s\n' "$REPLY"
    sanitize "${R_EVID[$id]}"
    ev=$REPLY
    while IFS= read -r line; do
        [[ -n $line ]] && wrap_lines 100 "    - " "      " "$line"
    done <<<"$ev"
    if [[ -n ${R_NOTE[$id]-} ]]; then
        sanitize "${R_NOTE[$id]}"
        wrap_lines 100 "    * " "      " "$REPLY"
    fi
}

report_text() {
    local out=$1 id s sec rule
    rule=$(printf '%0.s=' {1..100})
    {
        printf '%s\n' "$rule"
        printf '%s\n' "$CIS_BENCH_NAME $CIS_BENCH_VERSION - Level $LEVEL $PROFILE_LABEL audit report"
        printf '%s\n\n' "$rule"
        printf '%-22s %s\n' \
            "Host:" "$HOST_NAME" "FQDN:" "$HOST_FQDN" "OS release:" "$OS_PRETTY" "Kernel:" "$KERNEL" \
            "Run started:" "$RUN_START" "Run finished:" "$RUN_END" "Duration:" "${RUN_SECONDS}s" \
            "Benchmark:" "$CIS_BENCH_NAME $CIS_BENCH_VERSION" "Profile / level:" "$PROFILE_LABEL / Level $LEVEL (cumulative)" \
            "Script version:" "cis-audit $CIS_VERSION" "Catalog SHA-256:" "$SHA_CATALOG" \
            "site.conf SHA-256:" "$SHA_SITE" "exceptions.conf SHA-256:" "$SHA_EXC" "Options:" "$OPTS_GIVEN"
        printf '\nInternal compliance check, not an official CIS-CAT result.\n\n'

        printf '%s\n' "1. SUMMARY" "----------"
        for s in "${REPORT_STATES[@]}"; do printf '  %-10s %5d\n' "$s" "${CNT[$s]}"; done
        printf '  %-10s %s   (PASS / (PASS + FAIL))\n\n' "SCORE" "$SCORE_ALL"
        printf '  %-4s %-42s %5s %5s %5s %5s %5s %7s\n' Sec Section PASS FAIL MAN. N/A OTHER SCORE
        for sec in 1 2 3 4 5 6 7; do
            [[ -n ${SCNT[$sec:total]+x} ]] || continue
            score_str "${SCNT[$sec:PASS]:-0}" "${SCNT[$sec:FAIL]:-0}"
            printf '  %-4s %-42s %5d %5d %5d %5d %5d %7s\n' "$sec" "${SECTION_NAMES[$sec]}" \
                "${SCNT[$sec:PASS]:-0}" "${SCNT[$sec:FAIL]:-0}" "${SCNT[$sec:MANUAL]:-0}" "${SCNT[$sec:N/A]:-0}" \
                "$(( ${SCNT[$sec:total]} - ${SCNT[$sec:PASS]:-0} - ${SCNT[$sec:FAIL]:-0} - ${SCNT[$sec:MANUAL]:-0} - ${SCNT[$sec:N/A]:-0} ))" "$REPLY"
        done

        printf '\n%s\n' "2. FINDINGS (FAIL and ERROR)" "----------------------------"
        local any=0
        for id in "${RUN_IDS[@]}"; do
            [[ ${R_STATE[$id]} == FAIL || ${R_STATE[$id]} == ERROR ]] || continue
            any=1
            text_control_block "$id"
        done
        (( any )) || printf '  none\n'

        printf '\n%s\n' "3. MANUAL REVIEW" "----------------"
        any=0
        for id in "${RUN_IDS[@]}"; do
            [[ ${R_STATE[$id]} == MANUAL ]] || continue
            any=1
            text_control_block "$id"
        done
        (( any )) || printf '  none\n'

        printf '\n%s\n' "4. EXCEPTIONS" "-------------"
        any=0
        local left flag
        for id in $(printf '%s\n' "${!EXC_JUST[@]}" | sort_ids); do
            any=1
            days_left "${EXC_EXP[$id]}"
            left=$REPLY
            flag="$left days left"
            (( left < 0 )) && flag="EXPIRED $((-left)) days ago"
            sanitize "${EXC_JUST[$id]}"
            printf '  %s  state=%s  approved by %s  expires %s (%s)\n' "$id" "${R_STATE[$id]:-not-run}" "${EXC_BY[$id]}" "${EXC_EXP[$id]}" "$flag"
            wrap_lines 100 "      " "      " "$REPLY"
        done
        (( any )) || printf '  none\n'

        printf '\n%s\n' "5. FULL RESULTS" "---------------"
        for id in "${RUN_IDS[@]}"; do
            text_control_block "$id"
        done
    } >"$out"
}

# ==== lib/report_html.sh ====
# lib/report_html.sh - the self-contained HTML report.
# One file: inline CSS and plain JavaScript, no external fonts, CDNs or images.
# Every value taken from the host goes through html_escape (one helper, core.sh).
# shellcheck disable=SC2034

# esc <string>: E = html-escaped string (no subshell)
esc() { html_escape "$1"; E=$REPLY; }

html_style() {
    cat <<'CSS'
:root{--bg:#fff;--fg:#1d2330;--mut:#5b6475;--bd:#d6dae3;--card:#f5f6f9;--pass:#1a7f37;--fail:#c4262e;--exc:#8250df;--man:#b36b00;--na:#6e7781;--skip:#6e7781;--err:#c4262e}
@media (prefers-color-scheme:dark){:root{--bg:#14171d;--fg:#e4e7ee;--mut:#98a1b3;--bd:#30363f;--card:#1c2028;--pass:#3fb950;--fail:#ff6b6b;--exc:#b392f0;--man:#e3a53a;--na:#9aa3b2;--skip:#9aa3b2;--err:#ff6b6b}}
*{box-sizing:border-box}
body{margin:0;padding:16px;background:var(--bg);color:var(--fg);font:14px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
main{max-width:1100px;margin:0 auto}
h1{font-size:1.4rem;margin:.2rem 0 .6rem}h2{font-size:1.1rem;margin:1.6rem 0 .5rem;border-bottom:1px solid var(--bd);padding-bottom:.2rem}
table{border-collapse:collapse;width:100%;margin:.4rem 0}th,td{border:1px solid var(--bd);padding:.3rem .5rem;text-align:left;vertical-align:top}th{background:var(--card)}
td.n,th.n{text-align:right;font-variant-numeric:tabular-nums}
.meta td:first-child{width:14rem;color:var(--mut)}
.cards{display:flex;flex-wrap:wrap;gap:.5rem;margin:.6rem 0}.card{background:var(--card);border:1px solid var(--bd);border-radius:6px;padding:.4rem .8rem;min-width:7rem}
.card b{display:block;font-size:1.3rem}
.tools{display:flex;flex-wrap:wrap;gap:.4rem;align-items:center;margin:.6rem 0}
button,input{font:inherit;color:inherit;background:var(--card);border:1px solid var(--bd);border-radius:4px;padding:.25rem .6rem}
button.on{outline:2px solid var(--fg)}input{min-width:14rem}
.ctl{border:1px solid var(--bd);border-radius:6px;margin:.35rem 0;background:var(--card)}
.ctl>summary{cursor:pointer;padding:.35rem .6rem;list-style:none}
.ctl>summary::-webkit-details-marker{display:none}
.st{display:inline-block;min-width:5.6rem;font-weight:700;font-size:.85rem}
.s-PASS .st{color:var(--pass)}.s-FAIL .st,.s-ERROR .st{color:var(--fail)}.s-EXCEPTION .st{color:var(--exc)}.s-MANUAL .st{color:var(--man)}.s-NA .st,.s-SKIPPED .st{color:var(--na)}
.id{font-family:ui-monospace,Consolas,monospace;margin-right:.5rem}
.ev{margin:0;padding:.3rem .8rem .6rem 2rem}.ev li{margin:.1rem 0;word-break:break-word;white-space:pre-wrap}
.note{color:var(--mut);font-style:italic}
.hide{display:none}
@media print{.tools{display:none}.ctl{break-inside:avoid}.ctl>summary{display:block}details.ctl:not([open])>*:not(summary){display:block}body{background:#fff;color:#000}}
CSS
}

html_script() {
    cat <<'JS'
(function(){
var btns=document.querySelectorAll('[data-filter]'),q=document.getElementById('q'),
    ctls=document.querySelectorAll('#full .ctl'),active={};
function apply(){var any=Object.keys(active).length,t=(q.value||'').toLowerCase();
 ctls.forEach(function(c){var ok=(!any||active[c.getAttribute('data-state')]),
  h=c.querySelector('summary').textContent.toLowerCase();
  c.classList.toggle('hide',!(ok&&(!t||h.indexOf(t)>-1)));});}
btns.forEach(function(b){b.addEventListener('click',function(){var s=b.getAttribute('data-filter');
 if(s==='ALL'){active={};btns.forEach(function(x){x.classList.remove('on')});}
 else{if(active[s]){delete active[s];b.classList.remove('on');}else{active[s]=1;b.classList.add('on');}}
 apply();});});
q.addEventListener('input',apply);
document.getElementById('expand').addEventListener('click',function(){ctls.forEach(function(c){c.open=true})});
document.getElementById('collapse').addEventListener('click',function(){ctls.forEach(function(c){c.open=false})});
})();
JS
}

html_control() { # html_control <id> <open|"">
    local id=$1 st=${R_STATE[$1]} line cls est eid etitle
    cls=${st//\//}
    esc "$st"; est=$E
    esc "$id"; eid=$E
    sanitize "${CAT_TITLE[$id]}"; esc "$REPLY"; etitle=$E
    printf '<details class="ctl s-%s" data-state="%s"%s><summary><span class="st">%s</span><span class="id">%s</span>%s</summary>\n<ul class="ev">\n' \
        "$cls" "$cls" "${2:+ open}" "$est" "$eid" "$etitle"
    sanitize "${R_EVID[$id]}"
    local ev=$REPLY
    while IFS= read -r line; do
        if [[ -n $line ]]; then esc "$line"; printf '<li>%s</li>\n' "$E"; fi
    done <<<"$ev"
    if [[ -n ${R_NOTE[$id]-} ]]; then
        sanitize "${R_NOTE[$id]}"; esc "$REPLY"
        printf '<li class="note">%s</li>\n' "$E"
    fi
    printf '</ul></details>\n'
}

report_html() {
    local out=$1 id s sec left flag any k v e1 e2 e3 e4 e5
    {
        esc "$HOST_NAME"
        printf '<!doctype html>\n<html lang="en"><head><meta charset="utf-8">\n'
        printf '<meta name="viewport" content="width=device-width,initial-scale=1">\n'
        printf '<title>CIS audit %s</title>\n<style>\n' "$E"
        html_style
        printf '</style></head><body><main>\n'
        esc "$CIS_BENCH_NAME"; e1=$E
        esc "$CIS_BENCH_VERSION"; e2=$E
        esc "$LEVEL"; e3=$E
        esc "$PROFILE_LABEL"; e4=$E
        printf '<h1>%s %s &ndash; Level %s %s audit</h1>\n' "$e1" "$e2" "$e3" "$e4"
        printf '<p class="note">Internal compliance check, not an official CIS-CAT result.</p>\n'

        printf '<h2>Run</h2>\n<table class="meta">\n'
        while IFS='|' read -r k v; do
            esc "$k"; e1=$E
            esc "$v"; e2=$E
            printf '<tr><td>%s</td><td>%s</td></tr>\n' "$e1" "$e2"
        done <<EOF
Host|$HOST_NAME
FQDN|$HOST_FQDN
OS release|$OS_PRETTY
Kernel|$KERNEL
Run started|$RUN_START
Run finished|$RUN_END
Duration|${RUN_SECONDS}s
Benchmark|$CIS_BENCH_NAME $CIS_BENCH_VERSION
Profile / level|$PROFILE_LABEL / Level $LEVEL (cumulative)
Script version|cis-audit $CIS_VERSION
Catalog SHA-256|$SHA_CATALOG
site.conf SHA-256|$SHA_SITE
exceptions.conf SHA-256|$SHA_EXC
Options|$OPTS_GIVEN
EOF
        printf '</table>\n'

        printf '<h2>Summary</h2>\n<div class="cards">\n'
        for s in "${REPORT_STATES[@]}"; do
            esc "$s"
            printf '<div class="card"><b>%s</b>%s</div>\n' "${CNT[$s]}" "$E"
        done
        esc "$SCORE_ALL"
        printf '<div class="card"><b>%s</b>Score (PASS / (PASS + FAIL))</div>\n</div>\n' "$E"
        printf '<table><thead><tr><th>Section</th><th class="n">PASS</th><th class="n">FAIL</th><th class="n">EXCEPTION</th><th class="n">MANUAL</th><th class="n">N/A</th><th class="n">SKIPPED</th><th class="n">ERROR</th><th class="n">Score</th></tr></thead><tbody>\n'
        for sec in 1 2 3 4 5 6 7; do
            [[ -n ${SCNT[$sec:total]+x} ]] || continue
            score_str "${SCNT[$sec:PASS]:-0}" "${SCNT[$sec:FAIL]:-0}"
            esc "$REPLY"; e2=$E
            esc "${SECTION_NAMES[$sec]}"; e1=$E
            printf '<tr><td>%s %s</td>' "$sec" "$e1"
            for s in "${REPORT_STATES[@]}"; do printf '<td class="n">%s</td>' "${SCNT[$sec:$s]:-0}"; done
            printf '<td class="n">%s</td></tr>\n' "$e2"
        done
        printf '</tbody></table>\n'

        printf '<h2>Findings (FAIL and ERROR)</h2>\n'
        any=0
        for id in "${RUN_IDS[@]}"; do
            [[ ${R_STATE[$id]} == FAIL || ${R_STATE[$id]} == ERROR ]] || continue
            any=1
            html_control "$id" open
        done
        (( any )) || printf '<p>none</p>\n'

        printf '<h2>Manual review</h2>\n'
        any=0
        for id in "${RUN_IDS[@]}"; do
            [[ ${R_STATE[$id]} == MANUAL ]] || continue
            any=1
            html_control "$id" ""
        done
        (( any )) || printf '<p>none</p>\n'

        printf '<h2>Exceptions</h2>\n'
        if (( ${#EXC_JUST[@]} )); then
            printf '<table><thead><tr><th>ID</th><th>State</th><th>Justification</th><th>Approved by</th><th>Expires</th><th>Days left</th></tr></thead><tbody>\n'
            for id in $(printf '%s\n' "${!EXC_JUST[@]}" | sort_ids); do
                days_left "${EXC_EXP[$id]}"
                left=$REPLY
                flag=$left
                (( left < 0 )) && flag="EXPIRED ($left)"
                sanitize "${EXC_JUST[$id]}"; esc "$REPLY"; e3=$E
                esc "$id"; e1=$E
                esc "${R_STATE[$id]:-not run}"; e2=$E
                esc "${EXC_BY[$id]}"; e4=$E
                esc "${EXC_EXP[$id]}"; e5=$E
                printf '<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td>' "$e1" "$e2" "$e3" "$e4" "$e5"
                esc "$flag"
                printf '<td>%s</td></tr>\n' "$E"
            done
            printf '</tbody></table>\n'
        else
            printf '<p>none</p>\n'
        fi

        printf '<h2>Full results</h2>\n<div class="tools">\n<button data-filter="ALL">All</button>\n'
        for s in "${REPORT_STATES[@]}"; do
            esc "$s"
            printf '<button data-filter="%s">%s</button>\n' "${s//\//}" "$E"
        done
        printf '<input id="q" type="search" placeholder="Search ID or title" aria-label="Search ID or title">\n'
        printf '<button id="expand">Expand all</button><button id="collapse">Collapse all</button>\n</div>\n<div id="full">\n'
        for id in "${RUN_IDS[@]}"; do
            html_control "$id" ""
        done
        printf '</div>\n<script>\n'
        html_script
        printf '</script>\n</main></body></html>\n'
    } >"$out"
}
